const ROOM = "/rooms/connections";
const PAGE = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Your Connections</title><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link href=\"https://fonts.googleapis.com/css2?family=Marcellus&display=swap\" rel=\"stylesheet\"><style>body{margin:0;background:#050607;}\n.cx-stage{\n  --cx-purple:#8e24aa; --cx-purple-lt:#6d28d9;\n  position:relative;\n  margin:0; padding:36px clamp(20px,4vw,64px) 90px; color:#fff;\n  font-family:-apple-system,BlinkMacSystemFont,\"SF Pro Text\",Inter,\"Segoe UI\",sans-serif;\n  overflow:hidden;\n}\n/* living ambient light — slow drifting brand glows */\n.cx-stage .cx-ambient{ position:absolute; inset:0; pointer-events:none; z-index:0; overflow:hidden; }\n.cx-stage .cx-orb{\n  position:absolute; border-radius:50%; filter:blur(90px); opacity:.16;\n  animation:cxdrift 60s ease-in-out infinite alternate;\n}\n.cx-stage .cx-orb.o1{ width:520px; height:520px; left:-140px; top:-120px;\n  background:radial-gradient(circle, #8e24aa 0%, transparent 70%); }\n.cx-stage .cx-orb.o2{ width:460px; height:460px; right:-120px; top:30%;\n  background:radial-gradient(circle, #a21caf 0%, transparent 70%);\n  animation-delay:-9s; animation-duration:90s; }\n.cx-stage .cx-orb.o3{ width:420px; height:420px; left:20%; bottom:-160px;\n  background:radial-gradient(circle, #0f52ba 0%, transparent 70%);\n  animation-delay:-17s; animation-duration:120s; }\n@keyframes cxdrift{\n  from{ transform:translate(0,0) scale(1); }\n  to{ transform:translate(60px,40px) scale(1.12); }\n}\n.cx-stage > *:not(.cx-ambient){ position:relative; z-index:1; }\n.cx-stage .cx-head{ margin:0 0 22px; }\n.cx-hub-back{ display:inline-flex; align-items:center; height:38px; padding:0 15px; margin:0 0 16px; border-radius:999px; border:1px solid rgba(232,234,242,.35); background:rgba(255,255,255,.04); color:#fff; text-decoration:none; font:800 17px Inter,system-ui,sans-serif; letter-spacing:.06em; transition:border-color .15s ease, box-shadow .15s ease; }\n.cx-hub-back:hover{ border-color:#8e24aa; box-shadow:0 0 16px -4px #8e24aa; }\n.cx-stage .cx-kicker{\n  display:flex; align-items:center; gap:22px;\n  margin:0 0 14px;\n}\n/* pure white type, carved with light: crisp ground shadow,\n   luminous halo, breathing radiance */\n.cx-stage .cx-kicker-text{\n  font-family:\"Marcellus\", Georgia, serif;\n  font-size:44px; font-weight:600; letter-spacing:.02em; color:#fff;\n  white-space:nowrap; line-height:1.15;\n  text-shadow:\n    0 1px 0 rgba(255,255,255,.4),\n    0 3px 8px rgba(0,0,0,.75),\n    0 0 32px rgba(255,255,255,.3);\n  animation:cxtextbreathe 60s ease-in-out infinite;\n}\n.cx-stage .cx-kicker-text em{\n  font-style:italic; font-weight:500;\n}\n@keyframes cxtextbreathe{\n  0%,100%{ text-shadow:0 1px 0 rgba(255,255,255,.4), 0 3px 8px rgba(0,0,0,.75), 0 0 24px rgba(255,255,255,.24); }\n  50%{ text-shadow:0 1px 0 rgba(255,255,255,.45), 0 3px 8px rgba(0,0,0,.75), 0 0 44px rgba(255,255,255,.42); }\n}\n/* icon presence: radiant halo behind the mark, alive */\n/* section mark: black orb, light flowing around its edge */\n.cx-stage .cx-orb-icon{\n  position:relative; z-index:0; flex:0 0 auto; width:58px; height:58px; border-radius:50%;\n  background:radial-gradient(circle at 35% 28%, #332a4d 0%, #0d0a16 52%, #000 100%);\n  box-shadow:\n    inset 0 2px 5px rgba(255,255,255,.18),\n    inset 0 -8px 14px rgba(0,0,0,.65),\n    0 6px 16px rgba(0,0,0,.6),\n    0 0 24px rgba(142,36,170,.35);\n}\n/* white backlight — the halo that makes it a ball, not a disc */\n.cx-stage .cx-orb-icon::after{\n  content:''; position:absolute; inset:-20px; border-radius:50%; z-index:-1;\n  background:radial-gradient(circle,\n    rgba(255,255,255,.4) 0%,\n    rgba(255,255,255,.12) 42%,\n    transparent 68%);\n  animation:cxbackbreathe 60s ease-in-out infinite;\n}\n@keyframes cxbackbreathe{\n  0%,100%{ opacity:.75; transform:scale(.96); }\n  50%{ opacity:1; transform:scale(1.05); }\n}\n.cx-stage .cx-orb-icon::before{\n  content:''; position:absolute; inset:-4px; border-radius:50%;\n  background:conic-gradient(from 0deg,\n    transparent 0deg,\n    rgba(142,36,170,.95) 55deg,\n    rgba(255,255,255,.85) 85deg,\n    transparent 130deg,\n    transparent 360deg);\n  -webkit-mask:radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5px));\n  mask:radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5px));\n  animation:cxsheen 60s linear infinite;\n  filter:drop-shadow(0 0 6px rgba(142,36,170,.8));\n}\n.cx-stage .cx-logo{\n  flex:0 0 auto; width:58px; height:58px; border-radius:50%;\n  filter:drop-shadow(0 4px 10px rgba(0,0,0,.7)) drop-shadow(0 0 16px rgba(255,255,255,.4));\n}\n\n.cx-stage .cx-sub{\n  font-size:17px; line-height:1.65; color:#fff; margin:6px 0 0; font-weight:500; opacity:.94;\n  max-width:640px;\n}\n.cx-stage .cx-new{\n  flex:0 0 auto; display:flex; align-items:center; gap:8px;\n  padding:12px 20px; border-radius:999px; font-size:17px; font-weight:800; letter-spacing:.06em;\n  cursor:pointer; font-family:inherit; color:#fff; white-space:nowrap;\n  background:#050607; border:1.5px solid rgba(255,255,255,.4);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), 0 0 16px -2px rgba(255,255,255,.18), 0 4px 14px rgba(0,0,0,.5);\n  transition:border-color .22s, box-shadow .25s, transform .15s;\n}\n.cx-stage .cx-new:hover{\n  border-color:var(--cx-purple); transform:translateY(-1px);\n  box-shadow:0 0 26px -2px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.14);\n}\n.cx-stage .cx-nameform{\n  flex:0 0 auto; display:flex; align-items:center; gap:8px;\n  padding:6px 8px 6px 6px; border-radius:999px;\n  background:#050607; border:1.5px solid var(--cx-purple);\n  box-shadow:0 0 22px -4px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.12);\n}\n.cx-stage .cx-nameinput{\n  width:150px; padding:8px 12px; border:none; outline:none;\n  background:transparent; color:#fff; font-size:17px; font-family:inherit;\n}\n.cx-stage .cx-nameinput::placeholder{ color:rgba(255,255,255,.75); }\n.cx-stage .cx-namego{\n  padding:8px 16px; border-radius:999px; font-size:17px; font-weight:800;\n  cursor:pointer; font-family:inherit; color:#fff; letter-spacing:.08em;\n  background:#0d0817; border:1px solid var(--cx-purple);\n  box-shadow:0 0 16px -4px var(--cx-purple);\n}\n/* vertical contact cards */\n.cx-stage .cx-list{ display:flex; flex-direction:column; gap:14px; }\n.cx-stage .cx-empty{ color:#fff; opacity:.85; font-size:17px; padding:24px 0; }\n.cx-stage .cx-card{\n  position:relative; cursor:pointer;\n  display:flex; align-items:center; gap:18px;\n  border-radius:20px; padding:18px 22px;\n  background:linear-gradient(160deg, #17181d 0%, #08080a 100%);\n  border:1.5px solid rgba(255,255,255,.32);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), inset 0 -16px 30px rgba(0,0,0,.4), 0 0 18px -2px rgba(255,255,255,.12), 0 16px 40px rgba(0,0,0,.6);\n  animation:cxbreathe 60s ease-in-out infinite;\n  transition:transform .22s cubic-bezier(.2,.8,.2,1), border-color .25s, box-shadow .3s;\n  animation:cxin .5s cubic-bezier(.2,.8,.2,1) both;\n}\n@keyframes cxin{ from{ opacity:0; transform:translateY(14px);} to{ opacity:1; transform:none;} }\n@keyframes cxbreathe{\n  0%,100%{ box-shadow:inset 0 1px 0 rgba(255,255,255,.14), inset 0 -16px 30px rgba(0,0,0,.4), 0 0 14px -2px rgba(255,255,255,.1), 0 16px 40px rgba(0,0,0,.6); }\n  50%{ box-shadow:inset 0 1px 0 rgba(255,255,255,.18), inset 0 -16px 30px rgba(0,0,0,.4), 0 0 26px -2px rgba(255,255,255,.22), 0 16px 40px rgba(0,0,0,.6); }\n}\n.cx-stage .cx-card:hover, .cx-stage .cx-card:focus-visible{\n  transform:translateY(-2px); outline:none;\n  border-color:var(--cc);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), inset 0 -16px 30px rgba(0,0,0,.4), 0 22px 52px rgba(0,0,0,.65), 0 0 36px -4px var(--cc);\n}\n.cx-stage .cx-ava{\n  flex:0 0 auto; display:inline-flex; align-items:center; justify-content:center;\n  width:58px; height:58px; border-radius:50%;\n  font-size:22px; font-weight:900; color:#fff;\n  background:\n    radial-gradient(circle at 32% 28%, rgba(255,255,255,.35) 0%, rgba(255,255,255,0) 42%),\n    radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--cc) 55%, #101014) 0%, color-mix(in srgb, var(--cc) 28%, #060607) 78%);\n  border:2px solid color-mix(in srgb, var(--cc) 80%, white);\n  box-shadow:0 0 24px -4px var(--cc), inset 0 2px 3px rgba(255,255,255,.25), inset 0 -6px 12px rgba(0,0,0,.45), 0 8px 20px rgba(0,0,0,.55);\n  text-shadow:0 1px 3px rgba(0,0,0,.6);\n}\n.cx-stage .cx-ava.big{ width:78px; height:78px; font-size:30px; }\n.cx-stage .cx-ava::after{\n  content:''; position:absolute; inset:-2px; border-radius:50%;\n  background:conic-gradient(from 0deg, transparent 0deg, rgba(255,255,255,.35) 40deg, transparent 90deg);\n  animation:cxsheen 90s linear infinite; pointer-events:none;\n}\n.cx-stage .cx-ava{ position:relative; overflow:hidden; }\n@keyframes cxsheen{ to{ transform:rotate(360deg); } }\n.cx-stage .cx-info{ flex:1 1 auto; min-width:0; }\n.cx-stage .cx-name{ font-size:19px; font-weight:800; margin:0 0 4px; color:#fff; }\n.cx-stage .cx-role{ font-size:17px; color:#fff; opacity:.85; margin:0 0 4px; }\n.cx-stage .cx-in{ font-size:17px; color:#fff; opacity:.85; margin:0; letter-spacing:.03em; }\n.cx-stage .cx-go{\n  flex:0 0 auto; width:40px; height:40px; border-radius:50%;\n  display:flex; align-items:center; justify-content:center;\n  border:1px solid rgba(255,255,255,.25); color:#fff; font-size:18px;\n  background:#0a0a0c;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.12), 0 4px 12px rgba(0,0,0,.5);\n  transition:border-color .2s, box-shadow .25s;\n}\n.cx-stage .cx-card:hover .cx-go{\n  border-color:var(--cx-purple);\n  box-shadow:0 0 18px -4px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.12);\n}\n/* ═══ ROW FRAME — the Hub framed post (.intel-board), re-scoped to the\n   contact rows. Border declaration + edge-light bar are the post's own\n   (tone -> the person's --cc); the rows keep their harvested face. */\n.cx-stage .cx-card{ border: 2px solid color-mix(in srgb, var(--cc) 55%, #fff 14%); }\n.cx-stage .cx-card::before{\n  content: \"\"; position: absolute; left: 10px; top: 18px; bottom: 18px; width: 4px;\n  border-radius: 4px;\n  background: linear-gradient(135deg, var(--cc), color-mix(in srgb, var(--cc) 70%, #fff 12%), var(--cc));\n  box-shadow: 0 0 12px color-mix(in srgb, var(--cc) 55%, transparent);\n  pointer-events: none;\n}\n.cx-stage .cx-card:hover{ transform:translateY(-6px); } /* intel-board hover lift, fix2-base L1851 */\n.cx-stage .cx-mtop{ display:flex; gap:18px; align-items:center; margin-bottom:16px; }\n.cx-stage .cx-mname{ font-size:24px; font-weight:900; color:#fff; margin:0 0 6px; }\n.cx-stage .cx-mrole{ font-size:17px; color:#fff; opacity:.85; margin:0; }\n.cx-stage .cx-mnote{ font-size:18px; line-height:1.65; color:#fff; opacity:.92; margin:0 0 22px; font-weight:500; }\n.cx-stage .cx-mlabel{ font-size:17px; font-weight:800; letter-spacing:.18em; color:#fff; opacity:.85; margin:0 0 10px; }\n.cx-stage .cx-lpick{ display:flex; flex-wrap:wrap; gap:8px; margin-bottom:24px; }\n.cx-stage .cx-lbtn{\n  padding:10px 18px; border-radius:999px; font-size:17px; font-weight:700;\n  cursor:pointer; font-family:inherit; color:#fff;\n  background:#050607; border:1.5px solid rgba(255,255,255,.4);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.12), 0 0 14px -2px rgba(255,255,255,.16), 0 4px 12px rgba(0,0,0,.5);\n  transition:border-color .2s, box-shadow .25s;\n}\n.cx-stage .cx-lbtn:hover{ border-color:var(--cx-purple);\n  box-shadow:0 0 22px -4px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.12); }\n.cx-stage .cx-lbtn.in{\n  border-color:var(--cx-purple); background:#0a0714;\n  box-shadow:0 0 22px -2px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.14);\n}\n.cx-stage .cx-mrow{ display:flex; align-items:center; gap:14px; flex-wrap:wrap; margin-bottom:10px; }\n.cx-stage .cx-dstatus{ font-size:17px; color:#fff; opacity:.85; }\n.cx-stage .cx-honest{ font-size:17px; color:#fff; opacity:.85; margin:0 0 22px; }\n.cx-stage .cx-btn{\n  padding:12px 28px; border-radius:999px; font-size:17px; font-weight:800; letter-spacing:.12em;\n  cursor:pointer; font-family:inherit; color:#fff;\n  background:#050607; border:1.5px solid rgba(255,255,255,.4);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), 0 0 16px -2px rgba(255,255,255,.18), 0 6px 18px rgba(0,0,0,.55);\n  transition:border-color .22s, box-shadow .25s, transform .15s;\n}\n.cx-stage .cx-btn:hover, .cx-stage .cx-btn:focus-visible{\n  border-color:var(--cx-purple); outline:none; transform:translateY(-1px);\n  box-shadow:0 0 28px -2px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.14);\n}\n.cx-stage .cx-btn.ghost{ margin-top:2px; }\n/* ═══ SEARCH — find someone in seconds ═══ */\n.cx-stage .cx-search{margin:0 0 14px;}\n.cx-stage .cx-searchinput{width:100%;box-sizing:border-box;padding:16px 20px;border-radius:999px;\n  font-size:17px;font-family:inherit;color:#fff;background:#050607;border:1.5px solid rgba(255,255,255,.4);outline:none;}\n.cx-stage .cx-searchinput:focus{border-color:#8e24aa;box-shadow:0 0 26px -4px #8e24aa;}\n.cx-stage .cx-searchinput::placeholder{color:rgba(255,255,255,.75);}\n/* ═══ COUNT — the list, named ═══ */\n.cx-stage .cx-count{font-size:17px;font-weight:800;letter-spacing:.14em;color:#fff;margin:0 0 14px;}\n.cx-stage .cx-mbar{display:flex;justify-content:space-between;align-items:center;flex:0 0 auto;margin:0 0 18px;}\n.cx-stage .cx-mback{padding:10px 20px;border-radius:999px;font-size:17px;font-weight:800;letter-spacing:.06em;\n  cursor:pointer;font-family:inherit;color:#fff;background:#050607;border:1.5px solid rgba(255,255,255,.4);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), 0 4px 12px rgba(0,0,0,.5);}\n.cx-stage .cx-mback:hover{border-color:#8e24aa;box-shadow:0 0 22px -4px #8e24aa, inset 0 1px 0 rgba(255,255,255,.14);}\n/* ═══ CONNECT — the card's primary action, in the person's own colour ═══ */\n.cx-stage .cx-mact{margin-bottom:22px;}\n.cx-stage .cx-btn.cx-connect{border-color:var(--cc);\n  box-shadow:0 0 26px -4px var(--cc), inset 0 1px 0 rgba(255,255,255,.14), 0 6px 18px rgba(0,0,0,.55);}\n.cx-stage .cx-btn.cx-connect:hover{box-shadow:0 0 36px -2px var(--cc), inset 0 1px 0 rgba(255,255,255,.14);}\n@media(max-width:760px){\n  .cx-stage{ padding:28px 16px 70px; }\n  .cx-stage .cx-card{ padding:16px 18px; gap:14px; }\n  .cx-stage .cx-ava{ width:48px; height:48px; font-size:17px; }\n  /* D1 KICKER FIX — scale the kicker row so it fits on one line at phone\n     width. Desktop keeps the harvested 44px (whole at 1879px). */\n  .cx-stage .cx-kicker{ gap:12px; }\n  .cx-stage .cx-kicker-text{ font-size:28px; }\n  .cx-stage .cx-logo{ width:40px; height:40px; }\n  .cx-stage .cx-orb-icon{ width:40px; height:40px; }\n  .cx-stage .cx-cardbody{ padding:22px 18px 28px; }\n}\n@media(prefers-reduced-motion:reduce){\n  .cx-stage .cx-card, .cx-stage .cx-orb, .cx-stage .cx-ava::after, .cx-stage .cx-orb-icon::before, .cx-stage .cx-orb-icon::after, .cx-stage .cx-kicker-text{ animation:none; }\n  .cx-stage *{ transition:none !important; }\n}\n/* ═══ twin-plus chrome (harvested) ═══ */\n#os-chrome .rooms-plus,#os-chrome .eco-plus{position:fixed;top:12px;z-index:900;width:48px;height:48px;flex:none;display:grid;place-items:center;border-radius:50%;cursor:pointer;color:#fff;background:linear-gradient(180deg,#1b1b24,#07070b);border:1.5px solid #fff;box-shadow:inset 0 1px 0 rgba(255,255,255,.35),inset 0 -4px 8px rgba(0,0,0,.6),0 8px 20px rgba(0,0,0,.55);transition:border-color .25s,box-shadow .25s,transform .25s}\n#os-chrome .rooms-plus{left:12px;--jewel:#8e24aa}\n#os-chrome .eco-plus{right:12px;--jewel:#a21caf}\n#os-chrome .rooms-plus svg,#os-chrome .eco-plus svg{width:20px;height:20px}\n#os-chrome .rooms-plus:hover,#os-chrome .eco-plus:hover{transform:translateY(-2px) scale(1.04);border-color:var(--jewel);box-shadow:inset 0 1px 0 rgba(255,255,255,.5),inset 0 -3px 8px rgba(0,0,0,.4),0 0 32px var(--jewel),0 12px 28px rgba(0,0,0,.6)}\n:root{\n    --bg:#000; --ink:#f2f4fa;\n    --silver:#cfd3e0; --blue:#57b6ff; --gold:#f5c86b; --gold-bright:#ffe1a1;\n    --violet:#8b5cf6; --cyan:#3ca8ff; --dc:#3fb8ff;\n    --bw:64px;\n  }\n  @media(max-width:1024px){:root{--bw:44px}}\n  @media(max-width:640px){:root{--bw:16px}}\n/* ============ THE ROYAL FRAME (artwork embedded in this file) ============ */\n  .royal-frame{position:absolute;inset:0;z-index:40;pointer-events:none}\n  .royal-frame::after{content:\"\";position:absolute;inset:var(--bw) var(--bw) 14px var(--bw);border-radius:4px;pointer-events:none}\n  .royal-frame .rf-et{position:absolute;left:0;right:0;height:var(--bw);background-image:url(data:image/png;base64,);background-size:auto 100%;background-repeat:round no-repeat;background-position:0 0;pointer-events:none;-webkit-mask-image:linear-gradient(90deg,#000 0,#000 calc(50% - var(--bw)*1.254 - 48px),transparent calc(50% - var(--bw)*1.254),transparent calc(50% + var(--bw)*1.254),#000 calc(50% + var(--bw)*1.254 + 48px),#000 100%);mask-image:linear-gradient(90deg,#000 0,#000 calc(50% - var(--bw)*1.254 - 48px),transparent calc(50% - var(--bw)*1.254),transparent calc(50% + var(--bw)*1.254),#000 calc(50% + var(--bw)*1.254 + 48px),#000 100%)}\n  .royal-frame .rf-et.top{top:0}\n  .royal-frame .rf-es{position:absolute;top:0;bottom:0;width:var(--bw);background-image:url(data:image/png;base64,);background-size:var(--bw) calc(var(--bw)*2.1875);background-repeat:repeat-y;background-position:0 0;pointer-events:none}\n  .royal-frame .rf-es.left{left:0}\n  .royal-frame .rf-es.right{right:0}\n  .royal-frame .rf-rim{position:absolute;inset:var(--bw) var(--bw) 14px var(--bw);border:3px solid #ffffff;border-radius:4px;box-shadow:0 0 24px rgba(255,255,255,.55);pointer-events:none} /* RIM LIGHT WHITE (Shawn, 2026-11-22 ~09:47): steady white, not pink/purple. */\n  .royal-frame .rf-corner{position:absolute;width:var(--bw);height:var(--bw);background-size:91.67% 91.67%;background-position:center;background-repeat:no-repeat;pointer-events:none}\n  .royal-frame .rf-corner.tl{top:0;left:0;background-image:url(data:image/png;base64,)}\n  .royal-frame .rf-corner.tr{top:0;right:0;background-image:url(data:image/png;base64,)}\n  .royal-frame .rf-corner.bl{bottom:0;left:0;background-image:url(data:image/png;base64,)}\n  .royal-frame .rf-corner.br{bottom:0;right:0;background-image:url(data:image/png;base64,)}\n  .royal-frame .rf-n{position:absolute;top:0;left:50%;transform:translateX(-50%);height:var(--bw);width:calc(var(--bw)*632/252);background-image:url(data:image/png;base64,);background-size:100% 100%;background-repeat:no-repeat;pointer-events:none}\n/* ============ STAGE ============ */\n  /* D4: the frame wraps a page section: .stage's margin becomes the wrapper's\n     padding (the absolute frame insets against the padding box), and the\n     full-screen height + flex go — the section is content-height. */\n  .cx-framewrap{position:relative;padding:var(--bw) var(--bw) 14px;}\n  .cx-frameinner{flex:1;min-height:0;min-width:0;border:1px solid rgba(255,255,255,.75);box-shadow:0 0 0 1px rgba(0,0,0,.9),0 0 34px rgba(255,255,255,.35),inset 0 0 70px rgba(255,255,255,.06);background:#02030a;display:flex;flex-direction:column} /* WHITE ANGEL LIGHT (Shawn, 2026-11-22 ~15:42 MST): the frame edge is actual white light, shimmering — not pink, not violet. The shimmer rides in #school-3board below. */\n.pm-main{display:flex;gap:26px;padding:14px 22px 20px;align-items:flex-start;flex:1 1 auto;min-height:0}\n.ib-layer{--lc:#f4efff;flex:1;display:flex;border:2px solid color-mix(in srgb,var(--lc) 42%,#fff 8%);border-radius:18px;background:linear-gradient(135deg,#17171f,#0a0a10);box-shadow:0 14px 30px rgba(0,0,0,.56),0 0 34px -8px var(--lc);overflow:hidden;position:relative;animation:ib-breathe 6.5s ease-in-out infinite}\n  @keyframes ib-breathe{0%,100%{box-shadow:0 14px 30px rgba(0,0,0,.56),0 0 22px -6px var(--lc)}50%{box-shadow:0 14px 30px rgba(0,0,0,.56),0 0 46px -4px var(--lc)}}\n  .ib-layer::after{content:\"\";position:absolute;inset:0;border-radius:18px;padding:1.5px;pointer-events:none;z-index:0;background:conic-gradient(from var(--oa,0deg),transparent 0 205deg,rgba(255,255,255,.85) 292deg,#ffffff 320deg,transparent 360deg);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);mask-composite:exclude;animation:orbit-spin 12s linear infinite;opacity:.7;filter:drop-shadow(0 0 6px var(--lc))}\n@media(max-width:900px){\n    .pm-main{flex-direction:column;gap:16px;padding:12px 14px 16px}\n    .pm-art{flex:none;width:100%}\n    .pm-side{flex:none;width:100%;min-width:0;align-self:stretch}\n    .slide-boards{flex:none;width:100%;min-width:0}\n    #screen-slide .pm-art-frame{aspect-ratio:16/10}\n    .orb-wrap{width:168px;height:168px}\n  }\n/* ——— Smart Tabs v9: the pill ribbon. ———\n   Larger tactile pills, horizontal scroll with fade edges, the + Add control\n   as a dashed circle, glowing border on the active tab. System tabs (All +\n   per-topic) are permanent; human tabs are named views saved on this device.\n   The active tab wears the purple primary-action accent. */\n.smart-tabs {\n  display: flex; align-items: center; gap: 10px;\n  overflow-x: auto; scrollbar-width: none;\n  margin: 20px 0 0; padding: 12px 12px 18px; scroll-padding: 0 12px; /* EYE (g): the -6px pull cut the first/last tab labels at both edges — the strip now sits inside its box. */\n  border-bottom: 1px solid var(--line);\n  -webkit-mask-image: linear-gradient(90deg, #000, #000 calc(100% - 28px), transparent);\n  mask-image: linear-gradient(90deg, #000, #000 calc(100% - 28px), transparent);\n}\n.smart-tabs::-webkit-scrollbar { display: none; }\n.smart-tabs { scroll-behavior: smooth; -webkit-overflow-scrolling: touch; }\n.smart-tab { animation: tabIn .4s ease-out backwards; }\n.smart-tab:nth-child(1) { animation-delay: .05s; }\n.smart-tab:nth-child(2) { animation-delay: .1s; }\n.smart-tab:nth-child(3) { animation-delay: .15s; }\n.smart-tab:nth-child(4) { animation-delay: .2s; }\n.smart-tab:nth-child(5) { animation-delay: .25s; }\n.smart-tab:nth-child(6) { animation-delay: .3s; }\n.smart-tab:nth-child(7) { animation-delay: .35s; }\n.smart-tab:nth-child(8) { animation-delay: .4s; }\n@keyframes tabIn { from { opacity: 0; transform: translateY(8px) scale(.95); } to { opacity: 1; transform: translateY(0) scale(1); } }\n/* ——— SmartTabs v9 pill language (Naya 4's port) ———\n   Dark pill, bold label, per-tab spectrum color (--tc) that ignites\n   on hover/select. 💜 = purple inset glow, ⭐ = gold inset glow. */\n/* SmartTabs: white light at rest, lights ON (Shawn 2026-10-20) · color\n   ignites on hover; the active tab wears beautiful purple.\n   FIX-5a 2026-11-17 (amendment 3): the Record Law earning — --tc held 8\n   distinct colours the page never rendered, so all tabs read monochrome.\n   Each tab now wears its cluster color AT REST: rim + glow in --tc. */\n.smart-tab {\n  --tc: #8e24aa;\n  flex: 0 0 auto; display: inline-flex; align-items: center; gap: 10px;\n  padding: 12px 20px; border-radius: 999px; cursor: pointer; user-select: none;\n  border: 2px solid color-mix(in srgb, var(--tc) 68%, rgba(255,255,255,.35)); background: rgba(0,0,0,.55);\n  color: #fff; font-family: inherit; font-weight: 900; font-size: 17px; letter-spacing: .03em;\n  white-space: nowrap;\n  box-shadow: 0 0 18px color-mix(in srgb, var(--tc) 45%, transparent), inset 0 1px rgba(255,255,255,.18), inset 0 0 0 1px color-mix(in srgb, var(--tc) 30%, transparent);\n  transition: box-shadow .25s, border-color .2s, text-shadow .25s, transform .18s;\n}\n.smart-tab .sn-label { white-space: nowrap; }\n.smart-tab .sn-mark { font-size: 17px; line-height: 1; }\n.smart-tab:hover, .smart-tab:focus-visible {\n  border-color: var(--tc); outline: none; transform: translateY(-2px);\n  box-shadow: 0 0 22px -2px var(--tc), 0 0 0 2px var(--tc) inset;\n  text-shadow: 0 0 10px var(--tc);\n}\n/* Active: beautiful purple ignition (Shawn 2026-10-20) */\n.smart-tab.active {\n  border-color: #8e24aa;\n  box-shadow: 0 0 22px rgba(142,36,170,.55), inset 0 0 0 1.5px rgba(142,36,170,.8), inset 0 1px rgba(255,255,255,.2);\n  text-shadow: 0 0 10px rgba(142,36,170,.9);\n}\n.smart-tab.active:hover {\n  border-color: var(--tc);\n  box-shadow: 0 0 22px -2px var(--tc), 0 0 0 2px var(--tc) inset;\n  text-shadow: 0 0 10px var(--tc);\n}\n/* (5e) SMART TABS WEAR THE MODE-PILL TREATMENT, SMALLER. Harvested from\n   the lens tabs (.lens-tab + .primo, NAYA-BTN-005): obsidian pill, white\n   rim at rest, no colour wash inside; on hover and when active the rim and\n   the outside halo ignite in the tab's own deep colour with the same rich\n   glow the COLLECTIVE / PERSONAL / ACTIVITY buttons carry. The bright\n   first-letter table is gone from the tabs (tabColor now maps to the Laws\n   deep palette); the neon rainbow glow is out. */\n.smart-tab{border:2px solid rgba(255,255,255,.35);background:#050607;text-shadow:none;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.28),inset 0 -4px 10px rgba(0,0,0,.6),0 8px 20px rgba(0,0,0,.55);}\n.smart-tab:hover,.smart-tab:focus-visible{border-color:var(--tc);transform:translateY(-2px);text-shadow:none;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.28),inset 0 0 0 1.5px var(--tc),0 0 22px color-mix(in srgb,var(--tc) 55%,transparent),0 12px 28px rgba(0,0,0,.6);}\n.smart-tab.active{border-color:var(--tc);text-shadow:none;\n  box-shadow:inset 0 0 0 1.5px var(--tc),inset 0 -6px 14px rgba(0,0,0,.65),0 0 36px color-mix(in srgb,var(--tc) 75%,transparent),0 14px 36px rgba(0,0,0,.65);}\n.smart-tab.active:hover{border-color:var(--tc);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.28),inset 0 0 0 1.5px var(--tc),0 0 22px color-mix(in srgb,var(--tc) 55%,transparent),0 12px 28px rgba(0,0,0,.6);}\n/* ═══ AUTOORGANIZE GLUE — arrangement only, not parts. */\n.smart-tabs{ --line:#ffffff18; } /* Hub :root value, fix2-base L89 */\n.cx-cardview{ display:none; } /* the full-frame card view; JS shows it */\n.cx-third{ position:relative; z-index:1; flex:1; display:flex; flex-direction:column; min-width:0; padding:18px 20px 20px; }\n.cx-thirdhead{ font-size:17px; font-weight:800; letter-spacing:.14em; color:#fff; margin:0 0 14px; }\n.cx-third .cx-card{ margin:0 0 12px; }\n.cx-third .cx-card:last-child{ margin-bottom:0; }\n.cx-allsec{ padding:6px 22px 20px; }\n.cx-allhead{ font-size:17px; font-weight:800; letter-spacing:.14em; color:#fff; margin:0 0 14px; }\n.cx-cardbody{ position:relative; z-index:1; padding:28px 28px 34px; }\n.cx-note-make{ margin:18px 0 0; }\n.cx-note-make .cx-lk-editor{ margin:0 0 10px; }\n</style><style>\n/* ═══ #19 CUSTOM FIELDS & STAGES BY ASKING — additive layer ═══\n   Composed entirely from the room's own parts (.cx-mlabel, .cx-chip,\n   .cx-lbtn, .cx-draft, .cx-btn, .cx-honest, card shell values).\n   Obsidian at rest; ignition is the room's purple, edge only. */\n.cx-stage .cx-fx-panel{\n  position:relative; margin:0 0 22px; padding:22px;\n  border-radius:20px;\n  background:linear-gradient(160deg, #17181d 0%, #08080a 100%);\n  border:1.5px solid rgba(255,255,255,.32);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), inset 0 -16px 30px rgba(0,0,0,.4), 0 0 18px -2px rgba(255,255,255,.12), 0 16px 40px rgba(0,0,0,.6);\n  transition:border-color .25s, box-shadow .3s;\n}\n.cx-stage .cx-fx-panel:hover{\n  border-color:var(--cx-purple);\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), inset 0 -16px 30px rgba(0,0,0,.4), 0 22px 52px rgba(0,0,0,.65), 0 0 36px -4px var(--cx-purple);\n}\n.cx-stage .cx-fx-explain{ font-size:17px; line-height:1.6; color:#fff; opacity:.85; margin:0 0 14px; }\n.cx-stage .cx-fx-row{ display:flex; gap:10px; align-items:center; }\n.cx-stage .cx-fx-input{\n  flex:1 1 auto; min-width:0; box-sizing:border-box;\n  border-radius:14px; padding:12px 16px; font-size:17px; line-height:1.4; font-family:inherit;\n  color:#fff; background:rgba(0,0,0,.4); border:1px solid rgba(255,255,255,.14);\n}\n.cx-stage .cx-fx-input::placeholder{ color:rgba(255,255,255,.8); }\n.cx-stage .cx-fx-input:focus{ outline:none; border-color:var(--cx-purple); box-shadow:0 0 18px -6px var(--cx-purple); }\n.cx-stage .cx-fx-examples{ display:flex; flex-wrap:wrap; gap:8px; margin-top:12px; }\n.cx-stage .cx-fx-answer{ margin-top:14px; }\n.cx-stage .cx-fx-confirm{\n  border:1.5px solid var(--cx-purple); border-radius:16px; padding:14px 16px;\n  background:#0a0714; box-shadow:0 0 22px -6px var(--cx-purple), inset 0 1px 0 rgba(255,255,255,.12);\n}\n.cx-stage .cx-fx-heard{ font-size:17px; line-height:1.55; color:#fff; margin:0 0 12px; }\n.cx-stage .cx-fx-kindrow{ display:flex; flex-wrap:wrap; gap:8px; margin-bottom:12px; }\n.cx-stage .cx-fx-msg{ font-size:17px; line-height:1.55; color:#fff; opacity:.9; margin:0; }\n.cx-stage .cx-fx-defs{ margin-top:16px; }\n.cx-stage .cx-fx-defchips{ display:flex; flex-wrap:wrap; gap:8px; }\n.cx-stage .cx-fx-frow{ display:flex; gap:10px; align-items:center; margin-bottom:10px; }\n.cx-stage .cx-fx-flabel{ flex:0 0 30%; font-size:17px; font-weight:700; color:#fff; overflow-wrap:anywhere; }\n.cx-stage .cx-fx-finput{\n  flex:1 1 auto; min-width:0; box-sizing:border-box;\n  border-radius:14px; padding:10px 14px; font-size:17px; line-height:1.4; font-family:inherit;\n  color:#fff; background:rgba(0,0,0,.4); border:1px solid rgba(255,255,255,.14);\n}\n.cx-stage .cx-fx-finput::placeholder{ color:rgba(255,255,255,.8); }\n.cx-stage .cx-fx-finput:focus{ outline:none; border-color:var(--cx-purple); box-shadow:0 0 18px -6px var(--cx-purple); }\n.cx-stage .cx-btn.cx-fx-save{ padding:10px 18px; flex:0 0 auto; }\n@media(max-width:760px){\n  .cx-stage .cx-fx-panel{ padding:18px 16px; }\n  .cx-stage .cx-fx-frow{ flex-wrap:wrap; }\n  .cx-stage .cx-fx-flabel{ flex:1 1 100%; }\n}\n</style>\n<style>\n/* ═══ #14 LINKED EVERYTHING — additive layer ═══\n   Composed from the room's own parts (.cx-mlabel, .cx-lbtn, .cx-btn,\n   .cx-dstatus, .cx-honest, .cx-in card line; wells in the #19 facts\n   grammar). Obsidian at rest; ignition is the room's purple, edge only.\n   A filed note view is a framed well: the note itself, read live from\n   its own store — never a copy kept here. */\n.cx-stage .cx-lk-count:empty{ display:none; }\n.cx-stage .cx-lk-note{\n  border:1px solid rgba(255,255,255,.16); border-radius:16px;\n  background:rgba(0,0,0,.32); padding:14px 16px; margin:0 0 10px;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);\n}\n.cx-stage .cx-lk-title{ font-size:17px; font-weight:700; line-height:1.45; color:#fff; margin:0 0 4px; overflow-wrap:anywhere; }\n.cx-stage .cx-lk-body{ font-size:17px; line-height:1.6; color:#fff; opacity:.92; margin:0; white-space:pre-wrap; overflow-wrap:anywhere; }\n.cx-stage .cx-lk-meta{ font-size:17px; font-weight:600; color:#fff; opacity:.85; margin:8px 0 0; }\n.cx-stage .cx-lk-actions{ display:flex; flex-wrap:wrap; gap:8px; margin-top:10px; align-items:center; }\n.cx-stage .cx-lk-editor{\n  width:100%; box-sizing:border-box; margin-top:10px;\n  border-radius:14px; padding:10px 14px; font-size:17px; line-height:1.5; font-family:inherit;\n  color:#fff; background:rgba(0,0,0,.4); border:1px solid rgba(255,255,255,.14);\n  min-height:88px; resize:vertical;\n}\n.cx-stage .cx-lk-editor:focus{ outline:none; border-color:var(--cx-purple); box-shadow:0 0 18px -6px var(--cx-purple); }\n.cx-stage .cx-lk-pickrow{\n  display:flex; gap:10px; align-items:center; justify-content:space-between;\n  border:1px solid rgba(255,255,255,.12); border-radius:14px;\n  background:rgba(0,0,0,.25); padding:10px 12px; margin:0 0 8px;\n}\n.cx-stage .cx-lk-picktxt{ flex:1 1 auto; min-width:0; font-size:17px; line-height:1.45; color:#fff; overflow-wrap:anywhere; }\n.cx-stage .cx-lk-picktxt .cx-lk-meta{ margin:2px 0 0; }\n.cx-stage .cx-lk-filedmark{ font-size:17px; font-weight:700; color:#fff; opacity:.6; flex:0 0 auto; }\n.cx-stage .cx-mn-player{ display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:14px; background:rgba(255,255,255,.04); border:1px solid rgba(255,255,255,.14); margin-top:8px; }\n.cx-stage .cx-mn-play{ flex:0 0 auto; width:38px; height:38px; border-radius:50%; border:2px solid var(--cx-purple); background:#0a0a10; color:#fff; font-size:17px; cursor:pointer; }\n.cx-stage .cx-mn-wave{ flex:1; height:26px; display:flex; align-items:center; gap:2px; }\n.cx-stage .cx-mn-wave i{ flex:1; background:var(--cx-purple); opacity:.65; border-radius:2px; min-height:3px; }\n.cx-stage .cx-mn-dur{ font-size:17px; color:#ffffff; font-variant-numeric:tabular-nums; }\n.cx-stage .cx-mn-vidwrap{ position:relative; margin-top:8px; border-radius:14px; overflow:hidden; border:1px solid rgba(255,255,255,.14); background:#000; }\n.cx-stage .cx-mn-vidwrap video{ display:block; width:100%; max-height:300px; background:#000; }\n.cx-stage .cx-mn-vplay{ position:absolute; inset:0; display:flex; align-items:center; justify-content:center; background:rgba(0,0,0,.25); border:0; cursor:pointer; color:#fff; font-size:34px; }\n</style>\n</head><body>\n<div id=\"app\"></div>\n<script>function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined&&text!==null)e.textContent=text;return e;}window.NayaRooms=window.NayaRooms||{};window.ConnectionsAdapter=window.ConnectionsAdapter||{};\n  'use strict';\n\n  var KEY = 'naya.people.registry';\n\n  function clean(p){\n    if(!p || typeof p !== 'object' || p.id == null) return null;\n    return {\n      id: String(p.id),\n      name: String(p.name != null ? p.name : p.id),\n      role: String(p.role || ''),\n      color: String(p.color || '#8e24aa'),\n      note: String(p.note || '')\n    };\n  }\n\n  function load(){\n    try{\n      var raw = localStorage.getItem(KEY);\n      var a = raw ? JSON.parse(raw) : null;\n      if(!Array.isArray(a)) return null;\n      var out = [];\n      a.forEach(function(p){ var c = clean(p); if(c) out.push(c); });\n      return out;\n    }catch(e){ return null; }\n  }\n\n  function save(people){\n    try{ localStorage.setItem(KEY, JSON.stringify(people || [])); }catch(e){}\n  }\n\n  function ensureSeeded(ctxContacts){\n    var people = load();\n    if(people) return people;\n    people = [];\n    (Array.isArray(ctxContacts) ? ctxContacts : []).forEach(function(p){\n      var c = clean(p); if(c) people.push(c);\n    });\n    save(people);\n    return people;\n  }\n\n  function add(person){\n    var people = load() || [];\n    var c = clean(person);\n    if(c && !people.some(function(p){ return p.id === c.id; })){\n      people.push(c);\n      save(people);\n    }\n    return people;\n  }\n\n  function get(id){\n    var people = load() || [];\n    for(var i = 0; i < people.length; i++){\n      if(people[i].id === String(id)) return people[i];\n    }\n    return null;\n  }\n\n  window.NayaPeople = {\n    KEY: KEY,\n    load: load,\n    save: save,\n    ensureSeeded: ensureSeeded,\n    add: add,\n    get: get\n  };\n\n  'use strict';\n\n  function parseOne(c){\n    if(!c || typeof c !== 'object') return null;\n    if(!c.id || !c.name) return null;\n    return {\n      id:    String(c.id),\n      name:  String(c.name),\n      role:  c.role ? String(c.role) : '',\n      color: /^#[0-9a-fA-F]{6}$/.test(String(c.color||'')) ? String(c.color) : '#8e24aa',\n      kind:  c.kind === 'seat' ? 'seat' : 'person',\n      note:  c.note ? String(c.note) : ''\n    };\n  }\n\n  function parseContacts(raw){\n    var out = [];\n    var seen = {};\n    (Array.isArray(raw) ? raw : []).forEach(function(c){\n      try{\n        var p = parseOne(c);\n        if(p && !seen[p.id]){ seen[p.id] = true; out.push(p); }\n      }catch(err){ /* skip unparseable */ }\n    });\n    return out;\n  }\n\n  window.ConnectionsAdapter = { parseContacts: parseContacts };\n\n  'use strict';\n\n  var LS_LISTS = 'naya.connections.lists';\n\n  function loadLists(){\n    try{\n      var raw = localStorage.getItem(LS_LISTS);\n      if(raw){ var l = JSON.parse(raw); if(l && Array.isArray(l.lists)) return l; }\n    }catch(e){}\n    return null;\n  }\n\n  function seedLists(contacts){\n    return { lists:[{ id:'team-naya', name:'Team Naya',\n                      members: contacts.map(function(c){ return c.id; }) }] };\n  }\n\n  function saveLists(state){\n    try{ localStorage.setItem(LS_LISTS, JSON.stringify(state)); }catch(e){}\n  }\n\n\n  /* ═══ AUTO-ORGANIZER — the Hub's auto-organizer, extended to contacts.\n     The cluster table is the contact definition (family / business /\n     world + their keywords); the scoring loop is the Hub's own,\n     byte-identical (best keyword score wins). Manual wins: a category\n     you set on the card beats the scorer. No hits -> null: the contact\n     is uncategorized and shows under All only — never auto-filed into\n     a grouping it does not name. */\n  var LS_CATS = 'naya.connections.categories';\n  function loadCats(){\n    try{ var raw = localStorage.getItem(LS_CATS); if(raw){ var c = JSON.parse(raw); if(c && typeof c === 'object') return c; } }catch(e){}\n    return {};\n  }\n  function saveCats(cats){ try{ localStorage.setItem(LS_CATS, JSON.stringify(cats)); }catch(e){} }\n  const GEMATRIA_NUM = { A:1, B:2, C:3, D:4, E:5, F:6, G:7, H:6, I:5, J:4, K:3, L:2, M:1, N:1, O:2, P:3, Q:4, R:5, S:6, T:7, U:6, V:5, W:4, X:3, Y:2, Z:1 };\n  const GEMATRIA_COLOR = { 1:'#ff5e6c', 2:'#ff9a5a', 3:'#ffbf3d', 4:'#2fe89e', 5:'#29b6f6', 6:'#6675ff', 7:'#a06bff' };\n  function tabColor(key) {\n    const first = String(key || '').trim().charAt(0).toUpperCase();\n    var DEEP_TAB_COLOR={1:'#c62828',2:'#c2410c',3:'#d4a017',4:'#07925f',5:'#0e7490',6:'#3f51b5',7:'#8e24aa',8:'#6d28d9',9:'#a21caf'};\n    return DEEP_TAB_COLOR[GEMATRIA_NUM[first] || 7];\n  }\n  const CONTACT_CLUSTERS = [\n    { slug: 'family', label: 'Family', keys: ['family', 'mother', 'father', 'sister', 'brother', 'daughter', 'grandma', 'grandmother', 'grandfather', 'cousin', 'aunt', 'uncle', 'nephew', 'niece', 'wife', 'husband'] },\n    { slug: 'business', label: 'Business', keys: ['business', 'company', 'client', 'colleague', 'partner', 'vendor', 'investor', 'employer', 'employee', 'manager'] },\n    { slug: 'world', label: 'World', keys: ['world', 'community', 'citizen', 'neighbor', 'neighbour', 'friend', 'follower'] }\n  ];\n  function contactCategoryOf(c) {\n    const hay = ((c.name || '') + ' ' + (c.role || '') + ' ' + (c.note || '')).toLowerCase();\n    let best = null, bestScore = 0;\n    for (const c of CONTACT_CLUSTERS) {\n      let s = 0;\n      for (const k of c.keys) { if (hay.indexOf(k) !== -1) s += (k.length > 12 ? 3 : (k.indexOf(' ') !== -1 ? 2 : 1)); }\n      if (s > bestScore) { bestScore = s; best = c.slug; }\n    }\n    return best;\n  }\n  function effectiveCategory(c, cats){\n    if(cats && cats[c.id]) return cats[c.id];\n    return contactCategoryOf(c);\n  }\n\n  function Connections(el, ctx){\n    ctx = ctx || {};\n    var contacts = (window.NayaPeople && window.NayaPeople.ensureSeeded)\n      ? window.NayaPeople.ensureSeeded(ctx.contacts)\n      : (Array.isArray(ctx.contacts) ? ctx.contacts : []);\n    var byId = {};\n    contacts.forEach(function(c){ byId[c.id] = c; });\n\n    var store = loadLists() || seedLists(contacts);\n    store.lists.forEach(function(l){\n      l.members = l.members.filter(function(id){ return byId[id]; });\n    });\n    if(!store.lists.length) store = seedLists(contacts);\n    saveLists(store);\n\n    var state = { filter:'all', draftFor:null, q:'' };\n    /* active tab from ?category= — the Hub reads ?cluster= the same way. */\n    try{ var cq = (new URLSearchParams(location.search).get('category') || '').trim().toLowerCase().replace(/[^a-z0-9-]/g, '');\n      if(cq && CONTACT_CLUSTERS.some(function(c){ return c.slug === cq; })) state.filter = cq;\n    }catch(e){}\n\n    var stage = el('div','cx-stage');\n    /* views — GLUE: the list view and the full-frame card view live side by\n       side inside the stage; only one shows at a time. */\n    var listView = el('div','cx-listview'); stage.appendChild(listView);\n    var cardView = el('div','cx-cardview'); stage.appendChild(cardView);\n\n    var ambient = el('div','cx-ambient');\n    ['o1','o2','o3'].forEach(function(o){ ambient.appendChild(el('div','cx-orb '+o)); });\n    stage.appendChild(ambient);\n\n    var head = el('header','cx-head');\n    var kicker = el('p','cx-kicker','');\n    kicker.innerHTML = '<img class=\"cx-logo\" alt=\"NayaNET\" src=\"data:image/png;base64,\"/>'\n      + '<span class=\"cx-kicker-text\"><em>Your</em> Connections</span>'\n      + '<span class=\"cx-orb-icon\" aria-hidden=\"true\"></span>';\n    var hubBack = el('a','cx-hub-back','\\u2190 Hub');\n    hubBack.href = 'https://nayanet.app/#/hub/feed';\n    hubBack.setAttribute('aria-label','Back to the Hub');\n    head.appendChild(hubBack);\n    head.appendChild(kicker);\n    var sub = el('p','cx-sub','');\n    sub.textContent = 'Keep your people close \\u2014 organize them, remember them, reach them.';\n    head.appendChild(sub);\n    listView.appendChild(head);\n\n\n\n    /* top row — GLUE: the harvested + button + the harvested finder, side by side.\n       The + shows the list of all contacts (the harvested All action) and\n       smooth-scrolls to it (the harvested smooth scrollIntoView). */\n    var toprow = el('div','cx-toprow'); toprow.setAttribute('id','os-chrome');\n    var plus = el('button','rooms-plus'); plus.type='button'; plus.id='cx-plus';\n    plus.setAttribute('aria-label','Show all contacts');\n    plus.innerHTML = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.8\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M12 5v14M5 12h14\"/></svg>';\n    plus.addEventListener('click', function(){\n      searchInput.value=''; state.q=''; state.filter='all'; sync();\n      frameWrap.scrollIntoView({behavior:'smooth',block:'start'});\n    });\n    toprow.appendChild(plus);\n    var search = el('div','cx-search');\n    var searchInput = el('input','cx-searchinput','');\n    searchInput.type = 'text';\n    searchInput.setAttribute('placeholder','Search contacts');\n    searchInput.setAttribute('aria-label','Search contacts by name');\n    searchInput.addEventListener('input', function(){ state.q = searchInput.value; renderList(); });\n    search.appendChild(searchInput);\n    toprow.appendChild(search);\n    listView.appendChild(toprow);\n    /* ═══ AUTO-ORGANIZER TABS — the Hub's smart-tabs bar, applied to contacts.\n       One line under the search, above the frame. Tap a tab -> that grouping.\n       The pills are GLUE shaped on the Hub's snPill; the marquee + wheel\n       behaviours below are the Hub's own, harvested verbatim. */\n    var CONTACT_TABS = [{id:'all', label:'All', slug:null}].concat(CONTACT_CLUSTERS.map(function(c){ return {id:c.slug, label:c.label, slug:c.slug}; }));\n    var bar = el('div','smart-tabs');\n    bar.setAttribute('role','tablist');\n    bar.setAttribute('aria-label','Organize contacts by category');\n    function paintTabs(){\n      var pills = bar.querySelectorAll('.smart-tab');\n      pills.forEach(function(b){\n        var on = b.getAttribute('data-cat') === state.filter;\n        b.classList.toggle('active', on);\n        b.setAttribute('aria-selected', on ? 'true' : 'false');\n      });\n    }\n    CONTACT_TABS.forEach(function(t){\n      var b = el('button','smart-tab' + (t.id === state.filter ? ' active' : ''));\n      b.style.setProperty('--tc', tabColor(t.label));\n      b.setAttribute('role','tab');\n      b.setAttribute('aria-selected', t.id === state.filter ? 'true' : 'false');\n      b.setAttribute('data-cat', t.id);\n      b.title = t.slug ? 'Category \\u00B7 ' + t.label + ' \\u2014 your contacts, auto-organized' : 'The full list \\u2014 everyone, A to Z';\n      b.innerHTML = '<span class=\"sn-label\">' + t.label + '</span>';\n      b.addEventListener('click', function(){\n        state.filter = t.id; sync();\n        b.scrollIntoView({behavior:'smooth', inline:'nearest', block:'nearest'});\n      });\n      b.addEventListener('keydown', function(ev){\n        if(['ArrowRight','ArrowLeft','Home','End'].indexOf(ev.key) < 0) return;\n        ev.preventDefault();\n        var pills = Array.prototype.slice.call(bar.querySelectorAll('.smart-tab'));\n        var n = pills.indexOf(b);\n        if(ev.key === 'ArrowRight') n = Math.min(pills.length - 1, n + 1);\n        else if(ev.key === 'ArrowLeft') n = Math.max(0, n - 1);\n        else if(ev.key === 'Home') n = 0;\n        else n = pills.length - 1;\n        if(pills[n]) pills[n].focus();\n      });\n      bar.appendChild(b);\n    });\n/* ROUND 10 (item 5a — the checker's traverse arithmetic): the traverse is\n       DEFINED as one end-to-end pass, scrollLeft 0 -> max, and the step is\n       computed from the strip's own live width on every tick, so the pass\n       always takes 120 seconds — the middle of the Laws §1 60-180s ambient\n       band — at any viewport, on any tab count. At the checker's measured\n       1920 geometry (scrollWidth 25,879px, clientWidth 1,268px, pass\n       24,611px) the step is 24,611 x 16 / 120,000 = 3.28px per 16ms tick,\n       i.e. 205px/s, i.e. a 120s pass by construction. The old 1px/50ms\n       (20px/s) made the same pass 1,230s — twelve times the claim and\n       outside the band. It turns back at each end instead of jumping.\n       A hand on the strip pauses it; the citizen's own scroll or tap\n       pauses it for 8 seconds. One interval only — the old one is\n       cleared on every re-render. */\n    try{\n      if(window._stMarquee) clearInterval(window._stMarquee);\n      var _mDir=1, _mPauseUntil=0, _mTraverseMs=120000, _mTickMs=16;\n      bar.addEventListener('pointerenter', function(){ _mPauseUntil=Date.now()+8000; });\n      bar.addEventListener('pointerdown', function(){ _mPauseUntil=Date.now()+8000; });\n      bar.addEventListener('wheel', function(){ _mPauseUntil=Date.now()+8000; }, {passive:true});\n      bar.addEventListener('focusin', function(){ _mPauseUntil=Date.now()+8000; });\n      window._stMarquee=setInterval(function(){\n        if(document.hidden || Date.now()<_mPauseUntil) return;\n        var max=bar.scrollWidth-bar.clientWidth; if(max<=0) return;\n        bar.scrollLeft+=_mDir*(max*_mTickMs/_mTraverseMs);\n        if(bar.scrollLeft>=max) _mDir=-1; else if(bar.scrollLeft<=0) _mDir=1;\n      }, _mTickMs);\n    }catch(e){}\n/* AMENDMENT 2026-11-18 (D, Shawn 00:47Z): the tabs must scroll for a\n       mouse too. The overflow rule was already there (overflow-x:auto,\n       L1344) and touch/trackpad swipe already worked — but a desktop\n       wheel scrolls the PAGE vertically, so the row read as static and\n       clipped. A wheel over the strip now moves it sideways (deltaY →\n       scrollLeft), but only while the strip still has room to move that\n       way; at either end the page scrolls as normal. The fade edge and\n       the hidden scrollbar stay — the wheel is what desktop was missing. */\n    bar.addEventListener('wheel', function (ev) {\n      if (!ev.deltaY) return;\n      var max = bar.scrollWidth - bar.clientWidth;\n      if (max <= 0) return;\n      if ((ev.deltaY > 0 && bar.scrollLeft >= max) || (ev.deltaY < 0 && bar.scrollLeft <= 0)) return;\n      ev.preventDefault();\n      bar.scrollLeft = Math.max(0, Math.min(max, bar.scrollLeft + ev.deltaY));\n    }, { passive: false });\n    bar.scrollLeft = 0; /* FIX 2026-11-16 (item A), harvested: \"All\" fully in view at rest. */\n    listView.appendChild(bar);\n    var cxCount = el('p','cx-count','');\n    listView.appendChild(cxCount);\n    /* ═══ THE FRAME — the innovations royal frame wraps the middle boards.\n       The thirds row and the full list live inside it; search + tabs sit\n       above it. The frame markup is the innovations' own, verbatim. */\n    var frameWrap = el('div','cx-framewrap');\n    frameWrap.innerHTML = '<div class=\"royal-frame\" aria-hidden=\"true\"><div class=\"rf-et top\"></div><div class=\"rf-es left\"></div><div class=\"rf-es right\"></div><div class=\"rf-rim\"></div><div class=\"rf-corner tl\"></div><div class=\"rf-corner tr\"></div><div class=\"rf-corner bl\"></div><div class=\"rf-corner br\"></div><div class=\"rf-n top\"></div></div>';\n    var frameInner = el('div','cx-frameinner');\n    frameWrap.appendChild(frameInner);\n    listView.appendChild(frameWrap);\n    var thirds = el('div','pm-main');\n    frameInner.appendChild(thirds);\n    var allSec = el('div','cx-allsec');\n    var allHead = el('h2','cx-allhead',''); allSec.appendChild(allHead);\n    frameInner.appendChild(allSec);\n    var list = el('div','cx-list');\n    allSec.appendChild(list);\n\n    /* + Add person — harvested control, re-homed: the filters row is gone, so the\n       button and its name form live in their own row under the list. Same button,\n       same form, same commit; only the form's parent changed (filters -> addRow). */\n    var addRow = el('div','cx-addrow'); frameInner.appendChild(addRow);\n      var ap = el('button','cx-new','+ Add person'); ap.type='button';\n      ap.addEventListener('click', function(){\n        if(addRow.querySelector('.cx-nameform')) return;\n        var form = el('div','cx-nameform');\n        var nameIn = el('input','cx-nameinput',''); nameIn.type='text';\n        nameIn.setAttribute('placeholder','Person\\u2019s name\\u2026'); nameIn.setAttribute('maxlength','60'); nameIn.setAttribute('aria-label','New person name');\n        var roleIn = el('input','cx-nameinput',''); roleIn.type='text';\n        roleIn.setAttribute('placeholder','Role or how you know them\\u2026'); roleIn.setAttribute('maxlength','60'); roleIn.setAttribute('aria-label','New person role');\n        var go = el('button','cx-namego','Add'); go.type='button';\n        var cancel = function(){ if(form.parentNode) form.parentNode.removeChild(form); };\n        function commit(){\n          var name = nameIn.value.trim().slice(0,60);\n          if(!name){ nameIn.focus(); return; }\n          var role = roleIn.value.trim().slice(0,60);\n          var WALK = ['#8e24aa','#0f52ba','#07925f','#d4a017','#c2410c','#c62828','#a21caf'];\n          var person = { id:'p-'+Date.now().toString(36), name:name, role:role, color:WALK[contacts.length % WALK.length], kind:'person', note:'' };\n          if(window.NayaPeople && window.NayaPeople.add) window.NayaPeople.add(person);\n          contacts.push(person); byId[person.id] = person;\n          state.filter = 'all'; sync(); openCard(person);\n        }\n        go.addEventListener('click', commit);\n        [nameIn, roleIn].forEach(function(inp){ inp.addEventListener('keydown', function(ev){ if(ev.key==='Enter') commit(); if(ev.key==='Escape') cancel(); }); });\n        form.appendChild(nameIn); form.appendChild(roleIn); form.appendChild(go);\n        addRow.appendChild(form); nameIn.focus();\n      });\n      addRow.appendChild(ap);\n\n    function visible(){\n      var cats = loadCats();\n      var all = contacts.filter(function(c){\n        if(state.filter !== 'all' && effectiveCategory(c, cats) !== state.filter) return false;\n        return true;\n      });\n      var q = (state.q || '').trim().toLowerCase();\n      if(q) all = all.filter(function(c){ return c.name.toLowerCase().indexOf(q) >= 0; });\n      /* alphabetical by default — Shawn's call. A to Z, by name. */\n      return all.slice().sort(function(a, b){\n        return a.name.toLowerCase().localeCompare(b.name.toLowerCase());\n      });\n    }\n\n    function renderList(){\n      /* thirds — one panel per grouping, each its own view. A filtered tab\n         shows only its own panel; All shows all three. */\n      thirds.innerHTML = '';\n      var cats = loadCats();\n      var shown = ['family','business','world'].filter(function(slug){ return state.filter === 'all' || state.filter === slug; });\n      shown.forEach(function(slug){\n        var cat = CONTACT_CLUSTERS.filter(function(c){ return c.slug === slug; })[0];\n        var members = visible().filter(function(c){ return effectiveCategory(c, cats) === slug; });\n        var panel = el('div','ib-layer');\n        panel.setAttribute('data-cat', slug);\n        var pbody = el('div','cx-third');\n        var h = el('h3','cx-thirdhead','');\n        h.textContent = cat.label.toUpperCase() + ' \\u2014 ' + members.length;\n        pbody.appendChild(h);\n        if(!members.length){\n          pbody.appendChild(el('p','cx-empty','No one here yet.'));\n        }else{\n          members.forEach(function(c, i){ pbody.appendChild(card(c, i)); });\n        }\n        panel.appendChild(pbody);\n        thirds.appendChild(panel);\n      });\n      /* the full list, below the thirds, inside the same frame. */\n      list.innerHTML = '';\n      var people = visible();\n      allHead.textContent = state.filter === 'all' ? 'ALL CONTACTS' : (CONTACT_CLUSTERS.filter(function(c){ return c.slug === state.filter; })[0].label.toUpperCase());\n      cxCount.textContent = (state.q || state.filter !== 'all')\n        ? 'SHOWING ' + people.length + ' OF ' + contacts.length + ' PEOPLE'\n        : 'YOUR PEOPLE \\u2014 ' + contacts.length;\n      if(!people.length){\n        var e = el('p','cx-empty','');\n        e.textContent = state.filter !== 'all' ? 'No one in ' + (CONTACT_CLUSTERS.filter(function(c){ return c.slug === state.filter; })[0].label) + ' yet. Open a contact and add them to this category.' : (state.q ? 'No one matches that search.' : 'No contacts yet. Tap + Add person to add one.');\n        list.appendChild(e);\n      }else{\n        people.forEach(function(c, i){ list.appendChild(card(c, i)); });\n      }\n      paintTabs();\n    }\n\n    function card(c, i){\n      var a = el('article','cx-card');\n      a.style.setProperty('--cc', c.color);\n      a.style.animationDelay = Math.min(i*0.05, 0.6)+'s';\n      a.setAttribute('role','button'); a.setAttribute('tabindex','0');\n      a.setAttribute('aria-label','Open '+c.name);\n      var av = el('span','cx-ava',''); av.textContent = initials(c.name); a.appendChild(av);\n      var info = el('div','cx-info');\n      var nm = el('h2','cx-name',''); nm.textContent = c.name; info.appendChild(nm);\n      if(c.role){ var r = el('p','cx-role',''); r.textContent = c.role; info.appendChild(r); }\n      var cat = effectiveCategory(c, loadCats());\n      if(cat){ var m = el('p','cx-in',''); m.textContent = 'In: ' + (CONTACT_CLUSTERS.filter(function(x){ return x.slug === cat; })[0].label); info.appendChild(m); }\n      a.appendChild(info);\n      var go = el('span','cx-go',''); go.textContent = '+'; go.setAttribute('aria-hidden','true'); a.appendChild(go);\n      var open = function(){ openCard(c); };\n      a.addEventListener('click', open);\n      a.addEventListener('keydown', function(ev){\n        if(ev.key==='Enter'||ev.key===' '){ ev.preventDefault(); open(); }\n      });\n      return a;\n    }\n\n    function initials(name){\n      var w = String(name).trim().split(/\\s+/);\n      return (w[0]||'').charAt(0).toUpperCase();\n    }\n\n\n    /* ---------- full-frame card ----------\n       The calendar concept: a FULL frame around the person — their\n       profile, their information, everything we know about them,\n       organized in sections — plus MESSAGE + CONNECT, add-to-category\n       and the notes spot. No overlay, no floating popup. BACK returns\n       to the list inside the frame. */\n    var savedScroll = 0;\n    function openCard(c){\n      savedScroll = window.scrollY || document.documentElement.scrollTop || 0; /* FIX 2026-11-24: capture BEFORE any display swap — hiding the list clamps scrollY to 0 */\n      state.draftFor = c.id;\n      cardView.innerHTML = '';\n      var wrap = el('div','cx-framewrap');\n      wrap.innerHTML = '<div class=\"royal-frame\" aria-hidden=\"true\"><div class=\"rf-et top\"></div><div class=\"rf-es left\"></div><div class=\"rf-es right\"></div><div class=\"rf-rim\"></div><div class=\"rf-corner tl\"></div><div class=\"rf-corner tr\"></div><div class=\"rf-corner bl\"></div><div class=\"rf-corner br\"></div><div class=\"rf-n top\"></div></div>';\n      var inner = el('div','cx-frameinner');\n      wrap.appendChild(inner);\n      var body = el('div','cx-cardbody');\n      body.style.setProperty('--cc', c.color);\n      inner.appendChild(body);\n      /* BACK */\n      var mbar = el('div','cx-mbar');\n      var mback = el('button','cx-mback','\\u2190 BACK'); mback.type='button';\n      mback.setAttribute('aria-label','Back to your contacts');\n      mback.addEventListener('click', closeCard);\n      mbar.appendChild(mback); body.appendChild(mbar);\n      /* profile — the person */\n      var top = el('div','cx-mtop');\n      var av = el('span','cx-ava big',''); av.textContent = initials(c.name); top.appendChild(av);\n      var tt = el('div','');\n      var nm = el('h2','cx-mname',''); nm.textContent = c.name; tt.appendChild(nm);\n      if(c.role){ var r = el('p','cx-mrole',''); r.textContent = c.role; tt.appendChild(r); }\n      top.appendChild(tt);\n      body.appendChild(top);\n      if(c.note){ var n = el('p','cx-mnote',''); n.textContent = c.note; body.appendChild(n); }\n      /* MESSAGE + CONNECT */\n      var mact = el('div','cx-mrow cx-mact');\n      if(typeof ctx.onCompose === 'function'){\n        var wm = el('button','cx-btn','\\u2709  MESSAGE'); wm.type='button';\n        wm.addEventListener('click', function(){ ctx.onCompose(c); });\n        mact.appendChild(wm);\n      }\n      var connBtn = el('button','cx-btn cx-connect',''); connBtn.type='button';\n      var firstList = store.lists[0];\n      function paintConn(){\n        var isIn = firstList && firstList.members.indexOf(c.id) >= 0;\n        connBtn.textContent = isIn ? '\\u2713 CONNECTED' : '+ CONNECT';\n        connBtn.setAttribute('aria-pressed', isIn ? 'true' : 'false');\n      }\n      paintConn();\n      connBtn.addEventListener('click', function(){\n        if(!firstList) return;\n        if(firstList.members.indexOf(c.id) < 0){\n          firstList.members.push(c.id); saveLists(store);\n          if(window.NayaListSync) window.NayaListSync.push();\n          renderList();\n        }\n        paintConn();\n        paintCats();\n      });\n      mact.appendChild(connBtn);\n      body.appendChild(mact);\n      /* ADD TO CATEGORY — replaces save-to-list: one grouping per person,\n         tap to set, tap again to clear. */\n      body.appendChild(el('p','cx-mlabel','ADD TO CATEGORY'));\n      var lp = el('div','cx-lpick');\n      function paintCats(){\n        lp.innerHTML = '';\n        var cats = loadCats();\n        CONTACT_CLUSTERS.forEach(function(cat){\n          var has = effectiveCategory(c, cats) === cat.slug;\n          var b = el('button','cx-lbtn'+(has?' in':''), (has?'\\u2713 ':'+ ')+cat.label);\n          b.type='button'; b.setAttribute('aria-pressed', has?'true':'false');\n          b.addEventListener('click', function(){\n            var cats2 = loadCats();\n            if(cats2[c.id] === cat.slug) delete cats2[c.id];\n            else cats2[c.id] = cat.slug;\n            saveCats(cats2);\n            openCard(c); renderList();\n          });\n          lp.appendChild(b);\n        });\n      }\n      paintCats();\n      body.appendChild(lp);\n      /* facts & stages — everything we know, when there is any (S2 stays\n         silent when there is none: no error line, no dead guidance). */\n      if(window.NayaFacts) window.NayaFacts.renderInto(body, c, function(){ sync(); });\n      /* notes — the notes spot (S3): filed notes + make a note + file one\n         of your Naya Notes. Filed notes are the same notes as in Naya\n         Notes, read from their own rows, never copied. */\n      body.appendChild(el('p','cx-mlabel','NOTES ON '+c.name.toUpperCase()));\n      if(window.NayaLinks) window.NayaLinks.renderInto(body, c, function(){ sync(); });\n      cardView.appendChild(wrap);\n      listView.style.display = 'none';\n      cardView.style.display = 'block'; /* not '' — the glue rule hides .cx-cardview by default, so '' would stay hidden */\n      window.scrollTo(0, 0);\n      var first = lp.querySelector('.cx-lbtn'); if(first) first.focus();\n    }\n    function closeCard(){\n      cardView.style.display = 'none';\n      cardView.innerHTML = '';\n      listView.style.display = '';\n      state.draftFor = null;\n      window.scrollTo(0, savedScroll);\n    }\n    document.addEventListener('keydown', function(ev){\n      if(ev.key==='Escape' && cardView.style.display !== 'none') closeCard();\n    });\n\n    function timeAgo(iso){\n      var s = Math.max(0, Math.floor((Date.now()-new Date(iso).getTime())/1000));\n      if(s<60) return 'just now';\n      var m = Math.floor(s/60); return m<60 ? m+'m ago' : Math.floor(m/60)+'h ago';\n    }\n\n    function sync(){ renderList(); }\n    window.NayaCxLists = { getStore: function(){ return store; }, save: saveLists, sync: sync, byId: byId };\n    sync();\n    return stage;\n  }\n\n  window.NayaRooms = window.NayaRooms || {};\n  window.NayaRooms.connections = Connections;\nconst PACK=[{\"id\": \"shawn\", \"name\": \"Shawn Vibert\", \"role\": \"Human Director\", \"color\": \"#d4a017\", \"kind\": \"person\", \"note\": \"Final authority. The human everything is built for.\"}, {\"id\": \"naya1\", \"name\": \"Naya 1\", \"role\": \"Senior seat · integrator\", \"color\": \"#8e24aa\", \"kind\": \"seat\", \"note\": \"Primary integrator and director of the Hub build; Shawn assigned her the scorecard judge.\"}, {\"id\": \"naya2\", \"name\": \"Naya 2\", \"role\": \"Review lane\", \"color\": \"#0f52ba\", \"kind\": \"seat\", \"note\": \"Independent review lane — verifies, never duplicates. A trusted collaborator of a year.\"}, {\"id\": \"naya3\", \"name\": \"Naya 3\", \"role\": \"Design intelligence\", \"color\": \"#07925f\", \"kind\": \"seat\", \"note\": \"Design-intelligence builder — shipped the 11-room spec package; taste compiled into systems.\"}, {\"id\": \"naya4\", \"name\": \"Naya 4\", \"role\": \"Builder seat\", \"color\": \"#a21caf\", \"kind\": \"seat\", \"note\": \"Independent execution and proof closer — builds rooms and closes the proof.\"}];document.addEventListener('DOMContentLoaded',()=>{const contacts=ConnectionsAdapter.parseContacts(PACK);const onCompose=function(c){try{localStorage.setItem('naya.mail.compose.request',JSON.stringify({to:c.id,toKind:'person',ts:Date.now()}));}catch(e){}window.location.href='https://nayanet.app/rooms/mail';};document.getElementById('app').appendChild(window.NayaRooms.connections(el,{contacts:contacts,onCompose:onCompose}));});</script>\n<script>\n/* ════════════ #19 CUSTOM FIELDS & STAGES BY ASKING ════════════\n   The owner names their own facts and stages by asking, in plain words —\n   there is no field editor. Naya reads the ask back (confirm-the-parse);\n   one tap creates it. Definitions, per-person values and current stages\n   live in the owner's NayaNET store (public.custom_defs / person_values /\n   person_stages), seat flagship-personal, anon PostgREST — the same seat\n   the Today board and the #6 automations log prove. The room's people,\n   lists and notes stay device-local and untouched; this layer is guarded\n   (window.NayaFacts) so a store failure can never break the room. */\n(function(){\n'use strict';\nvar ALIAS='flagship-personal';\nvar SB='https://dahisasgpfvziswqvmvm.supabase.co/rest/v1';\nvar ANON='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRhaGlzYXNncGZ2emlzd3F2bXZtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc2MjM3ODgsImV4cCI6MjEwMzE5OTc4OH0.zX2r3T23sKebUMBdNg-4Noxos8JFOHaK2rRwqAVXU_s';\nvar CHIP_COLORS=['#8e24aa','#0f52ba','#07925f','#d4a017','#c2410c','#a21caf'];\n\nvar state={ defs:null, stages:{}, failed:false, panel:null, onReady:null };\n\nfunction el(tag, cls, text){\n  var e=document.createElement(tag);\n  if(cls) e.className=cls;\n  if(text!==undefined&&text!==null) e.textContent=text;\n  return e;\n}\nfunction req(method, path, body, prefer){\n  var opts={method:method, cache:'no-store',\n    headers:{'apikey':ANON,'Authorization':'Bearer '+ANON}};\n  if(body!==undefined){\n    opts.headers['Content-Type']='application/json';\n    opts.headers['Prefer']=prefer||'return=representation';\n    opts.body=JSON.stringify(body);\n  }\n  return fetch(SB+path, opts).then(function(r){\n    if(!r.ok) throw new Error('rest '+r.status);\n    return r.status===204 ? null : r.json();\n  });\n}\nfunction get(path){ return req('GET', path); }\n\nfunction fields(){ return (state.defs||[]).filter(function(d){ return d.kind==='field'; }); }\nfunction stages(){ return (state.defs||[]).filter(function(d){ return d.kind==='stage'; }); }\nfunction defById(id){\n  var ds=state.defs||[];\n  for(var i=0;i<ds.length;i++) if(ds[i].id===id) return ds[i];\n  return null;\n}\nfunction stageOf(personId){\n  var s=state.stages[personId];\n  if(!s) return null;\n  var d=defById(s);\n  return d ? d.name : null;\n}\n\nfunction load(){\n  return Promise.all([\n    get('/custom_defs?owner_alias=eq.'+ALIAS+'&select=id,kind,name,position&order=position.asc,created_at.asc'),\n    get('/person_stages?owner_alias=eq.'+ALIAS+'&select=person_id,def_id')\n  ]).then(function(res){\n    state.defs=res[0]||[];\n    state.stages={};\n    (res[1]||[]).forEach(function(r){ state.stages[r.person_id]=r.def_id; });\n    state.failed=false;\n    renderDefs();\n    if(state.onReady) state.onReady();\n  }).catch(function(){\n    state.failed=true;\n    renderDefs();\n    if(state.onReady) state.onReady();\n  });\n}\n\n/* ---------- the ask: parse + confirm-the-parse ---------- */\nfunction parseAsk(raw){\n  var t=String(raw||'').trim().replace(/\\s+/g,' ');\n  if(!t) return null;\n  function finish(kindWord, name){\n    name=String(name||'').trim().replace(/^[\"“]+|[\"”]+$/g,'').replace(/[.]+$/,'').slice(0,40);\n    if(!name) return null;\n    return { kind:(String(kindWord).toLowerCase()==='stage')?'stage':'field', name:name };\n  }\n  var m=t.match(/^(?:please[,\\s]+)?(?:add|create|make|new|track)\\s+(?:a\\s+|an\\s+|the\\s+)?(field|fact|stage)\\s+(?:called\\s+|named\\s+)?(.+)$/i);\n  if(m) return finish(m[1], m[2]);\n  m=t.match(/^(field|fact|stage)\\s*[:\\-]\\s*(.+)$/i);\n  if(m) return finish(m[1], m[2]);\n  m=t.match(/^(.+?)\\s+(field|fact|stage)$/i);\n  if(m) return finish(m[2], m[1]);\n  return null;\n}\n\nfunction addDef(kind, name, answerEl, input){\n  var dupe=(state.defs||[]).some(function(d){\n    return d.kind===kind && d.name.toLowerCase()===name.toLowerCase();\n  });\n  if(dupe){\n    answerEl.innerHTML='';\n    var dm=el('p','cx-fx-msg','You already have a '+(kind==='stage'?'STAGE':'FACT')+' called \\u201C'+name+'\\u201D \\u2014 it\\u2019s yours already.');\n    answerEl.appendChild(dm);\n    return Promise.resolve();\n  }\n  var pos=(state.defs||[]).filter(function(d){ return d.kind===kind; }).length;\n  return req('POST','/custom_defs',\n    { owner_alias:ALIAS, kind:kind, name:name, position:pos })\n  .then(function(){ return load(); })\n  .then(function(){\n    answerEl.innerHTML='';\n    var ok=el('p','cx-fx-msg','Done \\u2014 '+(kind==='stage'?'the STAGE':'the FACT')+' \\u201C'+name+'\\u201D is yours now. '+(kind==='stage' ? 'Open a person to move them into it.' : 'Open a person to write their '+name+'.'));\n    answerEl.appendChild(ok);\n    input.value='';\n  })\n  .catch(function(err){\n    if(String(err&&err.message).indexOf('409')>=0){\n      return load().then(function(){\n        answerEl.innerHTML='';\n        answerEl.appendChild(el('p','cx-fx-msg','You already have that one \\u2014 it\\u2019s yours already.'));\n        input.value='';\n      });\n    }\n    answerEl.innerHTML='';\n    answerEl.appendChild(el('p','cx-fx-msg','That didn\\u2019t save just now \\u2014 your words are still in the box above. Try ASK once more.'));\n  });\n}\n\nfunction showConfirm(parsed, answerEl, input){\n  answerEl.innerHTML='';\n  var box=el('div','cx-fx-confirm');\n  var cur={ kind:parsed.kind, name:parsed.name };\n  var heard=el('p','cx-fx-heard','');\n  function paintHeard(){\n    heard.textContent='I heard: a new '+(cur.kind==='stage'?'STAGE':'FACT')+' called \\u201C'+cur.name+'\\u201D.';\n  }\n  paintHeard();\n  box.appendChild(heard);\n  var kr=el('div','cx-fx-kindrow');\n  var bF=el('button','cx-lbtn'+(cur.kind==='field'?' in':''),'FACT'); bF.type='button';\n  var bS=el('button','cx-lbtn'+(cur.kind==='stage'?' in':''),'STAGE'); bS.type='button';\n  function setKind(k){\n    cur.kind=k;\n    bF.className='cx-lbtn'+(k==='field'?' in':'');\n    bS.className='cx-lbtn'+(k==='stage'?' in':'');\n    paintHeard();\n  }\n  bF.addEventListener('click', function(){ setKind('field'); });\n  bS.addEventListener('click', function(){ setKind('stage'); });\n  kr.appendChild(bF); kr.appendChild(bS);\n  box.appendChild(kr);\n  var row=el('div','cx-mrow');\n  var yes=el('button','cx-btn','YES, ADD IT'); yes.type='button';\n  yes.addEventListener('click', function(){ addDef(cur.kind, cur.name, answerEl, input); });\n  var no=el('button','cx-btn ghost','NOT THAT'); no.type='button';\n  no.addEventListener('click', function(){\n    answerEl.innerHTML='';\n    input.focus();\n  });\n  row.appendChild(yes); row.appendChild(no);\n  box.appendChild(row);\n  answerEl.appendChild(box);\n  yes.focus();\n}\n\n/* ---------- the ask panel ---------- */\nfunction renderDefs(){\n  if(!state.panel) return;\n  var host=state.panel.querySelector('.cx-fx-defs');\n  if(!host) return;\n  host.innerHTML='';\n  if(state.failed){\n    host.appendChild(el('p','cx-honest','Your facts and stages couldn\\u2019t be loaded just now \\u2014 nothing here is invented in their place.'));\n    return;\n  }\n  if(!state.defs) {\n    host.appendChild(el('p','cx-honest','Loading your facts and stages\\u2026'));\n    return;\n  }\n  if(!state.defs.length){\n    host.appendChild(el('p','cx-honest','You haven\\u2019t asked for any facts or stages yet. Ask above \\u2014 the first one takes ten seconds.'));\n    return;\n  }\n  host.appendChild(el('p','cx-mlabel','YOUR FACTS & STAGES'));\n  var wrap=el('div','cx-fx-defchips');\n  state.defs.forEach(function(d, i){\n    var b=el('span','cx-chip','');\n    b.style.setProperty('--bc', CHIP_COLORS[i % CHIP_COLORS.length]);\n    b.style.cursor='default';\n    var t=el('span','',d.name); b.appendChild(t);\n    var k=el('span','cx-chip-n', d.kind==='stage' ? 'STAGE' : 'FACT'); b.appendChild(k);\n    wrap.appendChild(b);\n  });\n  host.appendChild(wrap);\n}\n\nfunction mountAsk(container, onReady){\n  state.onReady=onReady||null;\n  var panel=el('section','cx-fx-panel');\n  panel.setAttribute('aria-label','Ask Naya for a fact or a stage');\n  panel.appendChild(el('p','cx-mlabel','ASK NAYA FOR A FACT OR A STAGE'));\n  panel.appendChild(el('p','cx-fx-explain','Tell Naya a fact you want to keep about your people \\u2014 \\u201CAdd a field called Budget\\u201D \\u2014 or a step they move through \\u2014 \\u201CAdd a stage called Waiting on contract\\u201D. You ask in plain words, Naya reads it back, and one tap makes it yours. There is no field editor here \\u2014 asking is the editor.'));\n  var row=el('div','cx-fx-row');\n  var input=el('input','cx-fx-input','');\n  input.type='text'; input.maxLength=80;\n  input.setAttribute('placeholder','Add a field called Budget\\u2026');\n  input.setAttribute('aria-label','Ask Naya for a fact or a stage');\n  var ask=el('button','cx-btn','ASK'); ask.type='button';\n  row.appendChild(input); row.appendChild(ask);\n  panel.appendChild(row);\n  var ex=el('div','cx-fx-examples');\n  ['Add a field called Budget','Add a stage called Waiting on contract'].forEach(function(x){\n    var b=el('button','cx-lbtn',x); b.type='button';\n    b.addEventListener('click', function(){ input.value=x; input.focus(); });\n    ex.appendChild(b);\n  });\n  panel.appendChild(ex);\n  var answer=el('div','cx-fx-answer');\n  panel.appendChild(answer);\n  var defs=el('div','cx-fx-defs');\n  panel.appendChild(defs);\n  var honest=el('p','cx-honest','Your facts and stages are saved in your NayaNET store \\u2014 not just on this device.');\n  honest.style.margin='14px 0 0';\n  panel.appendChild(honest);\n  container.appendChild(panel);\n  state.panel=panel;\n  function submit(){\n    var parsed=parseAsk(input.value);\n    answer.innerHTML='';\n    if(!parsed){\n      answer.appendChild(el('p','cx-fx-msg','I didn\\u2019t catch that. Try \\u201CAdd a field called Budget\\u201D or \\u201CAdd a stage called Waiting on contract\\u201D \\u2014 name it whatever you like.'));\n      return;\n    }\n    showConfirm(parsed, answer, input);\n  }\n  ask.addEventListener('click', submit);\n  input.addEventListener('keydown', function(ev){\n    if(ev.key==='Enter'){ ev.preventDefault(); submit(); }\n    if(ev.key==='Escape'){ answer.innerHTML=''; }\n  });\n  renderDefs();\n  load();\n}\n\n/* ---------- per-person sections (inside the detail modal) ---------- */\nfunction setStage(person, defId, pillsHost, refresh){\n  var done=function(){\n    if(defId) state.stages[person.id]=defId; else delete state.stages[person.id];\n    paintPills(person, pillsHost, refresh);\n    if(refresh) refresh();\n  };\n  if(defId){\n    req('POST','/person_stages?on_conflict=owner_alias,person_id',\n      { owner_alias:ALIAS, person_id:person.id, def_id:defId, updated_at:new Date().toISOString() },\n      'resolution=merge-duplicates,return=representation')\n    .then(done)\n    .catch(function(){ paintPills(person, pillsHost, refresh); });\n  }else{\n    req('DELETE','/person_stages?owner_alias=eq.'+ALIAS+'&person_id=eq.'+encodeURIComponent(person.id))\n    .then(done)\n    .catch(function(){ paintPills(person, pillsHost, refresh); });\n  }\n}\nfunction paintPills(person, host, refresh){\n  host.innerHTML='';\n  var cur=state.stages[person.id]||null;\n  var none=el('button','cx-lbtn'+(cur?'':' in'),'No stage'); none.type='button';\n  none.setAttribute('aria-pressed', cur?'false':'true');\n  none.addEventListener('click', function(){ if(cur) setStage(person, null, host, refresh); });\n  host.appendChild(none);\n  stages().forEach(function(d){\n    var b=el('button','cx-lbtn'+(cur===d.id?' in':''), (cur===d.id?'\\u2713 ':'+ ')+d.name);\n    b.type='button'; b.setAttribute('aria-pressed', cur===d.id?'true':'false');\n    (function(def){\n      b.addEventListener('click', function(){ if(cur!==def.id) setStage(person, def.id, host, refresh); });\n    })(d);\n    host.appendChild(b);\n  });\n}\n\nfunction renderInto(mcard, person, refresh){\n  if(state.failed || !state.defs){\n    return;\n  }\n  /* STAGE — shown only when stage definitions exist. */\n  if(stages().length){\n    mcard.appendChild(el('p','cx-mlabel','STAGE'));\n    var lp=el('div','cx-lpick');\n    mcard.appendChild(lp);\n    paintPills(person, lp, refresh);\n  }\n  /* YOUR FACTS */\n  mcard.appendChild(el('p','cx-mlabel','YOUR FACTS ABOUT '+person.name.toUpperCase()));\n  var fs=fields();\n  if(!fs.length){\n    return;\n  }\n  var host=el('div','');\n  mcard.appendChild(host);\n  get('/person_values?owner_alias=eq.'+ALIAS+'&person_id=eq.'+encodeURIComponent(person.id)+'&select=def_id,value')\n  .then(function(rows){\n    var byDef={};\n    (rows||[]).forEach(function(r){ byDef[r.def_id]=r.value; });\n    fs.forEach(function(d){\n      var row=el('div','cx-fx-frow');\n      var lab=el('span','cx-fx-flabel',d.name);\n      var inp=el('input','cx-fx-finput','');\n      inp.type='text'; inp.maxLength=200;\n      inp.value=byDef[d.id]||'';\n      inp.setAttribute('placeholder', d.name+' for '+person.name.split(/\\s+/)[0]+'\\u2026');\n      inp.setAttribute('aria-label', d.name+' for '+person.name);\n      var sv=el('button','cx-btn cx-fx-save','SAVE'); sv.type='button';\n      var st=el('span','cx-dstatus','');\n      (function(def, input, status){\n        sv.addEventListener('click', function(){\n          req('POST','/person_values?on_conflict=owner_alias,person_id,def_id',\n            { owner_alias:ALIAS, person_id:person.id, def_id:def.id, value:input.value.trim().slice(0,200), updated_at:new Date().toISOString() },\n            'resolution=merge-duplicates,return=representation')\n          .then(function(){ status.textContent='Saved just now.'; })\n          .catch(function(){ status.textContent='That didn\\u2019t save just now \\u2014 try SAVE once more.'; });\n        });\n        input.addEventListener('keydown', function(ev){ if(ev.key==='Enter'){ ev.preventDefault(); sv.click(); } });\n      })(d, inp, st);\n      row.appendChild(lab); row.appendChild(inp); row.appendChild(sv);\n      host.appendChild(row);\n      host.appendChild(st);\n    });\n  })\n  .catch(function(){});\n}\n\nwindow.NayaFacts={\n  stageOf:stageOf,\n  mountAsk:mountAsk,\n  renderInto:renderInto,\n  parseAsk:parseAsk,\n  _state:state\n};\n})();\n</script>\n<script>\n/* ════════════ #14 LINKED EVERYTHING — note ↔ person ════════════\n   One object, stored once, living in many homes. A link is a stored\n   row (public.object_links): a_kind/a_id ↔ b_kind/b_id, owner-scoped.\n   This layer files Naya Notes (a_kind 'note', rows in naya_notes) to\n   people (b_kind 'person', the room's registry ids) and renders each\n   filed note as a NO-COPY VIEW — title, body and category are read\n   from the note's own row at render time, never copied into the link\n   or this room. Edit the note here or in its home and both homes show\n   the same words. b_label is only the person's display name stamped\n   on the link for the note's home to show; the person's home (this\n   room) refreshes it to the truth on every render. Seat\n   flagship-personal, anon PostgREST — the Today / #6 / #19 seat.\n   Guarded (window.NayaLinks): a store failure can never break the\n   room, and a failed read shows an honest line, never invented data. */\n(function(){\n'use strict';\nvar ALIAS='flagship-personal';\nvar SB='https://dahisasgpfvziswqvmvm.supabase.co/rest/v1';\nvar ANON='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRhaGlzYXNncGZ2emlzd3F2bXZtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc2MjM3ODgsImV4cCI6MjEwMzE5OTc4OH0.zX2r3T23sKebUMBdNg-4Noxos8JFOHaK2rRwqAVXU_s';\n\nvar counts=null; /* person_id -> filed-note count; null until loaded */\n\nfunction el(tag, cls, text){\n  var e=document.createElement(tag);\n  if(cls) e.className=cls;\n  if(text!==undefined&&text!==null) e.textContent=text;\n  return e;\n}\nfunction req(method, path, body, prefer){\n  var opts={method:method, cache:'no-store',\n    headers:{'apikey':ANON,'Authorization':'Bearer '+ANON}};\n  if(body!==undefined){\n    opts.headers['Content-Type']='application/json';\n    opts.headers['Prefer']=prefer||'return=representation';\n    opts.body=JSON.stringify(body);\n  }\n  return fetch(SB+path, opts).then(function(r){\n    if(!r.ok) throw new Error('rest '+r.status);\n    return r.status===204 ? null : r.json();\n  });\n}\nfunction get(path){ return req('GET', path); }\nfunction relLabel(iso){\n  var ms=Date.now()-new Date(iso).getTime();\n  if(!(ms>=0)) return '';\n  if(ms<60000) return 'just now';\n  var m=Math.floor(ms/60000); if(m<60) return m+'m ago';\n  var h=Math.floor(m/60); if(h<24) return h+'h ago';\n  var d=Math.floor(h/24); return d+'d ago';\n}\nfunction firstLine(body, title){\n  if(title) return title;\n  var t=String(body||'').split('\\n')[0].trim();\n  return t.length>90 ? t.slice(0,90)+'\\u2026' : (t||'(a note with no words yet)');\n}\n\n/* ---------- card lines: \"Filed notes: N\" ---------- */\nfunction countLabel(personId){\n  if(!counts) return '';\n  var n=counts[personId]||0;\n  return n>0 ? ('Filed notes: '+n) : '';\n}\nfunction paintCounts(){\n  var spans=document.querySelectorAll('[data-lk-person]');\n  for(var i=0;i<spans.length;i++){\n    spans[i].textContent=countLabel(spans[i].getAttribute('data-lk-person'));\n  }\n}\nfunction loadCounts(){\n  var notesP=get('/object_links?owner_alias=eq.'+ALIAS+'&b_kind=eq.person&a_kind=eq.note&select=b_id');\n  var mediaP=get('/object_links?owner_alias=eq.'+ALIAS+'&b_kind=eq.person&a_kind=eq.media_note&select=b_id');\n  return Promise.all([notesP, mediaP])\n  .then(function(pair){\n    counts={};\n    (pair[0]||[]).concat(pair[1]||[]).forEach(function(r){ counts[r.b_id]=(counts[r.b_id]||0)+1; });\n    paintCounts();\n  })\n  .catch(function(){ counts=null; });\n}\n\n/* ---------- the modal section ---------- */\nfunction noteView(link, note, person, rerender){\n  var box=el('div','cx-lk-note');\n  if(!note){\n    box.appendChild(el('p','cx-lk-body','That note is no longer there \\u2014 it isn\\u2019t in Naya Notes anymore. Unfile to clear this link.'));\n    var arow0=el('div','cx-lk-actions');\n    var un0=el('button','cx-btn ghost','UNFILE'); un0.type='button';\n    un0.addEventListener('click', function(){ unfile(link.id, rerender); });\n    arow0.appendChild(un0);\n    box.appendChild(arow0);\n    return box;\n  }\n  if(note.title) box.appendChild(el('p','cx-lk-title',note.title));\n  var bodyText=String(note.body||'');\n  var bodyEl=el('p','cx-lk-body', bodyText.length>600 ? bodyText.slice(0,600)+'\\u2026' : bodyText);\n  box.appendChild(bodyEl);\n  var meta=relLabel(note.created_at)+(note.category ? ' \\u00B7 '+note.category : '');\n  box.appendChild(el('p','cx-lk-meta', meta));\n  var arow=el('div','cx-lk-actions');\n  var ed=el('button','cx-lbtn','EDIT THE NOTE'); ed.type='button';\n  var un=el('button','cx-btn ghost','UNFILE'); un.type='button';\n  var st=el('span','cx-dstatus','');\n  arow.appendChild(ed); arow.appendChild(un); arow.appendChild(st);\n  box.appendChild(arow);\n  var edHost=el('div','');\n  box.appendChild(edHost);\n  ed.addEventListener('click', function(){\n    if(edHost.firstChild){ edHost.innerHTML=''; ed.textContent='EDIT THE NOTE'; return; }\n    ed.textContent='CLOSE THE EDITOR';\n    var ta=el('textarea','cx-lk-editor','');\n    ta.value=String(note.body||'');\n    ta.setAttribute('aria-label','Edit the note filed here');\n    var srow=el('div','cx-lk-actions');\n    var sv=el('button','cx-btn','SAVE'); sv.type='button';\n    var sst=el('span','cx-dstatus','');\n    sv.addEventListener('click', function(){\n      var v=ta.value.trim();\n      if(!v){ sst.textContent='Write something first \\u2014 an empty note says nothing.'; return; }\n      req('PATCH','/naya_notes?id=eq.'+encodeURIComponent(note.id),\n        { body:v, updated_at:new Date().toISOString() })\n      .then(function(){\n        note.body=v;\n        bodyEl.textContent = v.length>600 ? v.slice(0,600)+'\\u2026' : v;\n        sst.textContent='Saved just now.';\n        st.textContent='Saved \\u2014 the same words now show in Naya Notes.';\n        edHost.innerHTML=''; ed.textContent='EDIT THE NOTE';\n      })\n      .catch(function(){ sst.textContent='That didn\\u2019t save just now \\u2014 try SAVE once more.'; });\n    });\n    srow.appendChild(sv); srow.appendChild(sst);\n    edHost.appendChild(ta); edHost.appendChild(srow);\n    ta.focus();\n  });\n  un.addEventListener('click', function(){ unfile(link.id, rerender, st); });\n  return box;\n}\n\nfunction unfile(linkId, rerender, statusEl){\n  req('DELETE','/object_links?id=eq.'+encodeURIComponent(linkId))\n  .then(function(){ loadCounts(); rerender(); })\n  .catch(function(){ if(statusEl) statusEl.textContent='Unfiling didn\\u2019t go through just now \\u2014 try once more.'; });\n}\n\n/* ---------- #20: filed voice/video notes (the recorded note kind) ---------- */\nfunction mnFmtDur(s){ s=Math.max(0,Math.round(s||0)); return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2); }\nfunction mnWave(seedStr){\n  var seed=0; for(var i=0;i<seedStr.length;i++) seed+=seedStr.charCodeAt(i);\n  var w=el('div','cx-mn-wave');\n  for(var j=0;j<28;j++){ var b=el('i',''); b.style.height=(4+((seed*(j+7))%20))+'px'; w.appendChild(b); }\n  return w;\n}\nfunction mediaView(link, m, person, rerender){\n  var box=el('div','cx-lk-note');\n  if(!m){\n    box.appendChild(el('p','cx-lk-body','That recording is no longer there \\u2014 it isn\\u2019t in your notes anymore. Unfile to clear this link.'));\n    var arow0=el('div','cx-lk-actions');\n    var un0=el('button','cx-btn ghost','UNFILE'); un0.type='button';\n    un0.addEventListener('click', function(){ unfile(link.id, rerender); });\n    arow0.appendChild(un0);\n    box.appendChild(arow0);\n    return box;\n  }\n  box.appendChild(el('p','cx-lk-title',(m.title||(m.kind==='video'?'Video note':'Voice note'))+' '+(m.kind==='video'?'\\uD83C\\uDFA5':'\\uD83C\\uDF99')));\n  var st=el('span','cx-dstatus','');\n  if(m.kind==='video'){\n    var vw=el('div','cx-mn-vidwrap');\n    var v=el('video',''); v.preload='metadata'; v.playsInline=true; v.src=m.media_url;\n    var ov=el('button','cx-mn-vplay','\\u25B6'); ov.type='button'; ov.setAttribute('aria-label','Play the video note');\n    ov.addEventListener('click', function(){ v.play().then(function(){ ov.style.display='none'; }, function(){ st.textContent='That recording is no longer there \\u2014 it may have been removed.'; }); });\n    v.addEventListener('click', function(){ if(!v.paused){ v.pause(); ov.style.display='flex'; } });\n    v.addEventListener('error', function(){ st.textContent='That recording is no longer there \\u2014 it may have been removed.'; });\n    vw.appendChild(v); vw.appendChild(ov); box.appendChild(vw);\n  }else{\n    var pl=el('div','cx-mn-player');\n    var pb=el('button','cx-mn-play','\\u25B6'); pb.type='button'; pb.setAttribute('aria-label','Play the voice note');\n    var audio=null;\n    pb.addEventListener('click', function(){\n      if(!audio){ audio=new Audio(); audio.preload='metadata'; audio.src=m.media_url;\n        audio.addEventListener('ended', function(){ pb.textContent='\\u25B6'; });\n        audio.addEventListener('error', function(){ st.textContent='That recording is no longer there \\u2014 it may have been removed.'; });\n      }\n      if(audio.paused){ audio.play().then(function(){ pb.textContent='\\u23F8'; }, function(){ st.textContent='That recording is no longer there \\u2014 it may have been removed.'; }); }\n      else { audio.pause(); pb.textContent='\\u25B6'; }\n    });\n    pl.appendChild(pb); pl.appendChild(mnWave(m.id));\n    pl.appendChild(el('span','cx-mn-dur', mnFmtDur(m.duration_s)));\n    box.appendChild(pl);\n  }\n  box.appendChild(el('p','cx-lk-meta', relLabel(m.created_at)+' \\u00B7 '+mnFmtDur(m.duration_s)+(m.category ? ' \\u00B7 '+m.category : '')));\n  if(m.summary){ box.appendChild(el('p','cx-lk-meta','SUMMARY')); box.appendChild(el('p','cx-lk-body', m.summary)); }\n  if(m.transcript){\n    box.appendChild(el('p','cx-lk-meta','TRANSCRIPT'));\n    var tt=String(m.transcript);\n    box.appendChild(el('p','cx-lk-body', tt.length>600 ? tt.slice(0,600)+'\\u2026' : tt));\n  }else if(m.status==='failed'){\n    box.appendChild(el('p','cx-lk-body','The transcript didn\\u2019t go through \\u2014 the recording itself is safe and playable above.'));\n  }else{\n    box.appendChild(el('p','cx-lk-body','Transcript on its way \\u2014 Naya is writing down what was said.'));\n  }\n  var arow=el('div','cx-lk-actions');\n  var un=el('button','cx-btn ghost','UNFILE'); un.type='button';\n  un.addEventListener('click', function(){ unfile(link.id, rerender, st); });\n  arow.appendChild(un); arow.appendChild(st);\n  box.appendChild(arow);\n  return box;\n}\n\nfunction picker(person, filedIds, mFiledIds, rerender){\n  var host=el('div','');\n  var toggle=el('button','cx-lbtn','FILE ONE OF YOUR NOTES'); toggle.type='button';\n  var listHost=el('div','');\n  listHost.style.marginTop='10px';\n  toggle.addEventListener('click', function(){\n    if(listHost.firstChild){ listHost.innerHTML=''; toggle.textContent='FILE ONE OF YOUR NOTES'; return; }\n    toggle.textContent='CLOSE THE LIST';\n    listHost.appendChild(el('p','cx-honest','Loading your notes\\u2026'));\n    get('/naya_notes?owner_alias=eq.'+ALIAS+'&select=id,title,body,category,created_at&order=created_at.desc&limit=100')\n    .then(function(notes){\n      listHost.innerHTML='';\n      var any=false;\n      if(notes && notes.length){\n        any=true;\n        notes.forEach(function(n){\n          var row=el('div','cx-lk-pickrow');\n          var txt=el('div','cx-lk-picktxt','');\n          txt.appendChild(document.createTextNode(firstLine(n.body, n.title)));\n          var m=relLabel(n.created_at)+(n.category ? ' \\u00B7 '+n.category : '');\n          txt.appendChild(el('p','cx-lk-meta', m));\n          row.appendChild(txt);\n          if(filedIds[n.id]){\n            row.appendChild(el('span','cx-lk-filedmark','Filed \\u2713'));\n          }else{\n            var fb=el('button','cx-lbtn','FILE'); fb.type='button';\n            (function(note){\n              fb.addEventListener('click', function(){\n                fb.textContent='FILING\\u2026';\n                req('POST','/object_links',\n                  { owner_alias:ALIAS, a_kind:'note', a_id:note.id, b_kind:'person', b_id:person.id, b_label:person.name })\n                .then(function(){ loadCounts(); rerender(); })\n                .catch(function(err){\n                  if(String(err&&err.message).indexOf('409')>=0){ loadCounts(); rerender(); return; }\n                  fb.textContent='FILE';\n                });\n              });\n            })(n);\n            row.appendChild(fb);\n          }\n          listHost.appendChild(row);\n        });\n      }\n      return get('/media_notes?owner_alias=eq.'+ALIAS+'&select=id,kind,title,duration_s,category,created_at&order=created_at.desc&limit=100')\n      .then(function(media){\n        if(media && media.length){\n          any=true;\n          listHost.appendChild(el('p','cx-mlabel','VOICE & VIDEO NOTES'));\n          media.forEach(function(mn){\n            var row=el('div','cx-lk-pickrow');\n            var txt=el('div','cx-lk-picktxt','');\n            txt.appendChild(document.createTextNode((mn.kind==='video'?'\\uD83C\\uDFA5 ':'\\uD83C\\uDF99 ')+(mn.title||(mn.kind==='video'?'Video note':'Voice note'))));\n            var mm=mnFmtDur(mn.duration_s)+' \\u00B7 '+relLabel(mn.created_at)+(mn.category ? ' \\u00B7 '+mn.category : '');\n            txt.appendChild(el('p','cx-lk-meta', mm));\n            row.appendChild(txt);\n            if(mFiledIds[mn.id]){\n              row.appendChild(el('span','cx-lk-filedmark','Filed \\u2713'));\n            }else{\n              var fb=el('button','cx-lbtn','FILE'); fb.type='button';\n              (function(mnote){\n                fb.addEventListener('click', function(){\n                  fb.textContent='FILING\\u2026';\n                  req('POST','/object_links',\n                    { owner_alias:ALIAS, a_kind:'media_note', a_id:mnote.id, b_kind:'person', b_id:person.id, b_label:person.name })\n                  .then(function(){ loadCounts(); rerender(); })\n                  .catch(function(err){\n                    if(String(err&&err.message).indexOf('409')>=0){ loadCounts(); rerender(); return; }\n                    fb.textContent='FILE';\n                  });\n                });\n              })(mn);\n              row.appendChild(fb);\n            }\n            listHost.appendChild(row);\n          });\n        }\n        if(!any){\n          /* no notes yet — the composer above is the spot. */\n        }\n      })\n      .catch(function(){\n        if(!any){\n          /* no notes yet — the composer above is the spot. */\n        }\n      });\n    })\n    .catch(function(){\n      listHost.innerHTML='';\n      /* the notes list stays empty when the store cannot be reached. */\n    });\n  });\n  host.appendChild(toggle);\n  host.appendChild(listHost);\n  return host;\n}\n\n\nfunction renderInto(mcard, person, refresh){\n\n  var host=el('div','');\n  mcard.appendChild(host);\n  function rerender(){ renderSection(host, person, refresh, rerender); if(refresh) refresh(); }\n  renderSection(host, person, refresh, rerender);\n\n}\n\n/* MAKE A NOTE — the notes spot's composer (GLUE): write a note about\n   this person right here. It composes two proven-live operations: anon\n   INSERT into naya_notes + POST object_links (the picker's own FILE\n   action). One tap creates the note in Naya Notes and files it here. */\nfunction composer(person, rerender){\n  var box = el('div','cx-note-make');\n  box.appendChild(el('p','cx-mlabel','MAKE A NOTE'));\n  var ta = el('textarea','cx-lk-editor','');\n  ta.setAttribute('placeholder','Write a note about '+person.name+'\\u2026');\n  ta.setAttribute('aria-label','Write a note about '+person.name);\n  var row = el('div','cx-lk-actions');\n  var add = el('button','cx-btn','ADD NOTE'); add.type='button';\n  var st = el('span','cx-dstatus','');\n  row.appendChild(add); row.appendChild(st);\n  box.appendChild(ta); box.appendChild(row);\n  add.addEventListener('click', function(){\n    var v = ta.value.trim();\n    if(!v){ st.textContent='Write something first \\u2014 an empty note says nothing.'; return; }\n    add.disabled = true; add.textContent='ADDING\\u2026';\n    var title = v.split('\\n')[0].trim().slice(0,90) || ('Note on '+person.name);\n    req('POST','/naya_notes',{ owner_alias:ALIAS, title:title, body:v, category:'Smart Note' })\n    .then(function(rows){\n      var note = rows && rows[0];\n      if(!note || !note.id) throw new Error('no note id');\n      return req('POST','/object_links',{ owner_alias:ALIAS, a_kind:'note', a_id:note.id, b_kind:'person', b_id:person.id, b_label:person.name })\n      .then(function(){ return note; })\n      .catch(function(){\n        st.textContent='Saved in Naya Notes \\u2014 filing it here didn\\u2019t go through. Find it in the list below and tap FILE.';\n        add.disabled = false; add.textContent='ADD NOTE';\n        loadCounts(); rerender();\n        return null;\n      });\n    })\n    .then(function(note){\n      if(!note) return;\n      ta.value=''; st.textContent='Saved just now \\u2014 the same note now shows in Naya Notes.';\n      add.disabled = false; add.textContent='ADD NOTE';\n      loadCounts(); rerender();\n    })\n    .catch(function(){\n      st.textContent='That didn\\u2019t save just now \\u2014 try ADD NOTE once more.';\n      add.disabled = false; add.textContent='ADD NOTE';\n    });\n  });\n  return box;\n}\n\nfunction renderSection(host, person, refresh, rerender){\n  host.innerHTML='';\n  host.appendChild(el('p','cx-honest','Loading filed notes…'));\n  var noteLinksP=get('/object_links?owner_alias=eq.'+ALIAS+'&b_kind=eq.person&b_id=eq.'+encodeURIComponent(person.id)+'&a_kind=eq.note&select=id,a_id,b_label,created_at&order=created_at.asc');\n  var mediaLinksP=get('/object_links?owner_alias=eq.'+ALIAS+'&b_kind=eq.person&b_id=eq.'+encodeURIComponent(person.id)+'&a_kind=eq.media_note&select=id,a_id,b_label,created_at&order=created_at.asc');\n  Promise.all([noteLinksP, mediaLinksP])\n  .then(function(pair){\n    var links=pair[0], mlinks=pair[1];\n    (links||[]).concat(mlinks||[]).forEach(function(l){\n      if(l.b_label!==person.name){\n        req('PATCH','/object_links?id=eq.'+encodeURIComponent(l.id), { b_label:person.name }).catch(function(){});\n      }\n    });\n    var ids=(links||[]).map(function(l){ return l.a_id; });\n    var mids=(mlinks||[]).map(function(l){ return l.a_id; });\n    var notesP = ids.length\n      ? get('/naya_notes?id=in.('+ids.map(encodeURIComponent).join(',')+')&select=id,title,body,category,created_at')\n      : Promise.resolve([]);\n    var mediaP = mids.length\n      ? get('/media_notes?id=in.('+mids.map(encodeURIComponent).join(',')+')&select=id,kind,title,media_url,duration_s,category,transcript,summary,status,created_at')\n      : Promise.resolve([]);\n    return Promise.all([notesP, mediaP]).then(function(np){\n      var notes=np[0], media=np[1];\n      var byId={};\n      (notes||[]).forEach(function(n){ byId[n.id]=n; });\n      var mById={};\n      (media||[]).forEach(function(n){ mById[n.id]=n; });\n      var filedIds={};\n      (links||[]).forEach(function(l){ filedIds[l.a_id]=true; });\n      var mFiledIds={};\n      (mlinks||[]).forEach(function(l){ mFiledIds[l.a_id]=true; });\n      host.innerHTML='';\n      if((!links || !links.length) && (!mlinks || !mlinks.length)){\n        /* no notes filed yet — the composer below is the spot. */\n      }else{\n        (links||[]).forEach(function(l){ host.appendChild(noteView(l, byId[l.a_id]||null, person, rerender)); });\n        (mlinks||[]).forEach(function(l){ host.appendChild(mediaView(l, mById[l.a_id]||null, person, rerender)); });\n      }\n      host.appendChild(composer(person, rerender));\n      host.appendChild(picker(person, filedIds, mFiledIds, rerender));\n    });\n  })\n  .catch(function(){\n    host.innerHTML='';\n    /* the filed list could not be read — the composer still shows. */\n    host.appendChild(composer(person, rerender));\n  });\n}\n\nwindow.NayaLinks={\n  countLabel:countLabel,\n  paintCounts:paintCounts,\n  renderInto:renderInto,\n  _loadCounts:loadCounts\n};\nloadCounts();\n})();\n</script>\n<script>\n/* ════════════ SMART LISTS SYNC (2026-10-23) ════════════\n   This room's lists are the owner's Smart Lists — the ONE server store\n   (public.smart_lists / smart_list_items, seat flagship-personal) that\n   the flagship Lists view reads. Filing a person here files them there;\n   a list made in either place is the same list. Guarded like the #19\n   layer: if the store cannot be reached, the room keeps working on its\n   device lists exactly as before — this layer can never break the room,\n   and it never claims a sync that did not happen. */\n(function(){\n'use strict';\nvar ALIAS = 'flagship-personal';\nvar SB = 'https://dahisasgpfvziswqvmvm.supabase.co/rest/v1';\nvar ANON = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImRhaGlzYXNncGZ2emlzd3F2bXZtIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODc2MjM3ODgsImV4cCI6MjEwMzE5OTc4OH0.zX2r3T23sKebUMBdNg-4Noxos8JFOHaK2rRwqAVXU_s';\nvar hook = null, snapshot = null, pushTimer = null, booted = false, tries = 0;\n\nfunction req(method, path, body){\n  var opts = { method: method, headers: { 'apikey': ANON, 'Authorization': 'Bearer ' + ANON, 'Content-Type': 'application/json' } };\n  if (body !== undefined){ opts.body = JSON.stringify(body); opts.headers['Prefer'] = 'return=representation'; }\n  return fetch(SB + path, opts).then(function(r){ if (!r.ok) throw new Error('store ' + r.status); return r.status === 204 ? null : r.json(); });\n}\nfunction isUuid(id){ return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(id || '')); }\nfunction personName(id){ var c = hook && hook.byId ? hook.byId[id] : null; return c ? c.name : String(id); }\n\nfunction fetchServer(){\n  return Promise.all([\n    req('GET', '/smart_lists?owner_alias=eq.' + ALIAS + '&select=id,title,position,created_at&order=position.asc,created_at.asc'),\n    req('GET', '/smart_list_items?owner_alias=eq.' + ALIAS + '&item_kind=eq.person&select=id,list_id,item_ref,label&order=created_at.asc')\n  ]).then(function(out){\n    var lists = out[0] || [], items = out[1] || [];\n    var byList = {};\n    items.forEach(function(it){ (byList[it.list_id] = byList[it.list_id] || []).push(it); });\n    return { lists: lists, items: items, byList: byList };\n  });\n}\n\nfunction adopt(server){\n  var store = hook.getStore();\n  var roomLists = store.lists.slice();\n  var merged = [];\n  var snapLists = {}, snapItems = {};\n  var serverIds = {};\n  server.lists.forEach(function(sl){\n    serverIds[sl.id] = true;\n    var members = (server.byList[sl.id] || []).map(function(it){ return it.item_ref; });\n    (server.byList[sl.id] || []).forEach(function(it){ snapItems[sl.id + '|' + it.item_ref] = it.id; });\n    snapLists[sl.id] = true;\n    merged.push({ id: sl.id, name: sl.title, members: members });\n  });\n  roomLists.forEach(function(rl){\n    if (isUuid(rl.id) && !serverIds[rl.id]) return; /* a server list deleted elsewhere — the server is its truth */\n    var target = null;\n    merged.forEach(function(ml){ if (ml.name === rl.name) target = ml; });\n    if (target){\n      rl.members.forEach(function(id){ if (target.members.indexOf(id) < 0) target.members.push(id); });\n    } else {\n      merged.push({ id: rl.id, name: rl.name, members: rl.members.slice() });\n    }\n  });\n  store.lists = merged;\n  snapshot = { lists: snapLists, items: snapItems };\n  hook.save(store);\n  hook.sync();\n}\n\nfunction push(){\n  if (!hook || !snapshot) return;\n  if (pushTimer) clearTimeout(pushTimer);\n  pushTimer = setTimeout(runPush, 500);\n}\nfunction runPush(){\n  if (!hook || !snapshot) return;\n  var store = hook.getStore();\n  var chain = Promise.resolve();\n  store.lists.forEach(function(l){\n    if (!isUuid(l.id)){\n      chain = chain.then(function(){\n        return req('POST', '/smart_lists', { owner_alias: ALIAS, title: l.name, category: 'General', position: 0 }).then(function(rows){\n          if (rows && rows[0]){ l.id = rows[0].id; snapshot.lists[l.id] = true; hook.save(store); }\n        });\n      });\n    }\n  });\n  chain = chain.then(function(){\n    var want = {};\n    store.lists.forEach(function(l){\n      if (!isUuid(l.id)) return;\n      l.members.forEach(function(ref){ want[l.id + '|' + ref] = { listId: l.id, ref: ref }; });\n    });\n    var ops = [];\n    Object.keys(want).forEach(function(k){\n      if (!snapshot.items[k]) ops.push(req('POST', '/smart_list_items', { owner_alias: ALIAS, list_id: want[k].listId, item_kind: 'person', item_ref: want[k].ref, label: personName(want[k].ref) }).then(function(rows){ if (rows && rows[0]) snapshot.items[k] = rows[0].id; }));\n    });\n    Object.keys(snapshot.items).forEach(function(k){\n      if (!want[k]){ var itemId = snapshot.items[k]; ops.push(req('DELETE', '/smart_list_items?id=eq.' + itemId).then(function(){ delete snapshot.items[k]; })); }\n    });\n    return Promise.all(ops);\n  }).then(function(){ hook.save(store); }, function(){ /* snapshot untouched — the next push retries the diff */ });\n}\n\nfunction boot(){\n  if (booted) return;\n  hook = window.NayaCxLists || null;\n  if (!hook){ if (++tries <= 20) setTimeout(boot, 300); return; }\n  booted = true;\n  fetchServer().then(function(server){\n    adopt(server);\n    push(); /* uploads anything the device had that the server did not */\n  }, function(){ /* store unreachable: the room stays device-local, as before */ });\n}\n\nwindow.NayaListSync = { push: push };\nif (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\nelse boot();\n})();\n\n</script>\n</body></html>";
const MANIFEST = "{\"background_color\":\"#000000\",\"description\":\"Your Connections \u2014 the people in your world, and how you are linked to each of them inside NayaNET.\",\"display\":\"standalone\",\"icons\":[{\"purpose\":\"any\",\"sizes\":\"192x192\",\"src\":\"/rooms/connections/icons/naya-icon-192.png\",\"type\":\"image/png\"},{\"purpose\":\"any\",\"sizes\":\"512x512\",\"src\":\"/rooms/connections/icons/naya-icon-512.png\",\"type\":\"image/png\"},{\"purpose\":\"maskable\",\"sizes\":\"512x512\",\"src\":\"/rooms/connections/icons/naya-icon-512.png\",\"type\":\"image/png\"}],\"id\":\"/rooms/connections\",\"name\":\"Your Connections \u2014 NayaNET\",\"orientation\":\"portrait\",\"scope\":\"/rooms/connections/\",\"short_name\":\"Your Connections\",\"start_url\":\"/rooms/connections\",\"theme_color\":\"#000000\"}";
const SW = "/* Your Connections service worker \u2014 offline shell for the installed app.\n   Keeps Connections reachable when the network drops. Scoped to /rooms/connections/ only,\n   so it can never touch the Hub or any other room. */\n/* ROUND 4 CURE (2026-10-22): page loads are NETWORK-FIRST (below) and the\n   cache name moved v1 -> v2, so activate purges the v1 cache that was\n   trapping readers on the first-cached page forever. */\nconst CACHE = 'smart-connections-v2';\nconst CORE = [\n  './',\n  './manifest.json',\n  './icons/naya-icon-192.png',\n  './icons/naya-icon-512.png',\n  './icons/apple-touch-icon.png'\n];\n\nself.addEventListener('install', (e) => {\n  e.waitUntil(\n    caches.open(CACHE)\n      .then((c) => Promise.allSettled(CORE.map((u) => c.add(u))))\n      .then(() => self.skipWaiting())\n  );\n});\n\nself.addEventListener('activate', (e) => {\n  e.waitUntil(\n    caches.keys()\n      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))\n      .then(() => self.clients.claim())\n  );\n});\n\nself.addEventListener('fetch', (e) => {\n  if (e.request.method !== 'GET') return;\n  const url = new URL(e.request.url);\n  if (url.origin !== location.origin) return;\n  /* Only ever serve our own scope \u2014 never proxy other apps' traffic. */\n  if (!url.pathname.startsWith('/rooms/connections')) return;\n\n  const isPage = e.request.mode === 'navigate'\n    || url.pathname === '/rooms/connections' || url.pathname === '/rooms/connections/';\n\n  if (isPage) {\n    /* NETWORK-FIRST for the page itself: fresh bytes win on every load\n       and refresh the cache; the cache answers only when offline.\n       (v1 served the page cache-first under a cache name that never\n       changed \u2014 the first cached page was served forever, and no\n       update ever reached the reader.) */\n    e.respondWith(\n      fetch(e.request).then((res) => {\n        if (res && res.ok) {\n          const copy = res.clone();\n          caches.open(CACHE).then((c) => c.put(e.request, copy));\n        }\n        return res;\n      }).catch(() => caches.match(e.request, { ignoreSearch: true })\n        .then((hit) => hit || caches.match('./')))\n    );\n    return;\n  }\n\n  /* Static shell (icons, manifest): cache-first is safe \u2014 they never\n     carry page updates. */\n  e.respondWith(\n    caches.match(e.request).then((hit) => hit || fetch(e.request).then((res) => {\n      const copy = res.clone();\n      caches.open(CACHE).then((c) => c.put(e.request, copy));\n      return res;\n    }))\n  );\n});\n";
const ICONS = {
  "naya-icon-192.png": { type: "image/png", b64: "" },
  "naya-icon-512.png": { type: "image/png", b64: "" },
  "apple-touch-icon.png": { type: "image/png", b64: "" }
};
function b64ToBytes(s) {
  const bin = atob(s);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
export default {
  fetch(req) {
    const url = new URL(req.url);
    const p = url.pathname;
    if (p.endsWith("/manifest.json")) {
      return new Response(MANIFEST, { headers: {
        "content-type": "application/manifest+json;charset=utf-8",
        "cache-control": "no-cache" } });
    }
    if (p.endsWith("/sw.js")) {
      return new Response(SW, { headers: {
        "content-type": "application/javascript;charset=utf-8",
        "cache-control": "no-cache" } });
    }
    const iconMatch = p.match(/\/icons\/([A-Za-z0-9\-_.]+)$/);
    if (iconMatch && ICONS[iconMatch[1]]) {
      const ic = ICONS[iconMatch[1]];
      return new Response(b64ToBytes(ic.b64), { headers: {
        "content-type": ic.type,
        "cache-control": "public, max-age=86400" } });
    }
    if (p === ROOM || p === ROOM + "/" || p === "/") {
      return new Response(PAGE, { headers: {
        "content-type": "text/html;charset=utf-8",
        "cache-control": "no-store, no-cache, must-revalidate" } });
    }
    return new Response("not found", { status: 404 });
  }
};

